DATA_LOADED("tuhfa",[["مقدمة",["بسم الله الرحمن الرحيم","الحمد لله الذي يقضي ولا ... يقضى عليه جل شأنا وعلا","ثم الصلاة بدوام الأبد ... على الرسول المصطفى محمد","وآله والفئة المتبعه ... في كل ما قد سنه وشرعه","وبعد، فالقصد بهذا الرجز ... تقرير الاحكام بلفظ موجز","آثرت فيه الميل للتبيين ... وصنته جهدي من التضمين","وجئت في بعض من المسائل ... بالخلف رعيا لاشتهار القائل","فضمنه المفيد والمقرب ... والمقصد المحمود والمنتخب","نظمته تذكرة وحيث تم ... بما به البلوى تعم قد ألم","سميته بتحفة الحكام ... في نكت العقود والأحكام","وذاك لما أن بليت بالقضا ... بعد شباب مر عني وانقضى","وإنني أسأل من رب قضى ... به علي الرفق منه في القضا","والحمل والتوفيق أن أكون ... من أمة بالحق يعدلون","حتى أرى من مفرد الثلاثه ... وجنة الفردوس لي وراثه"],[]],["باب القضاء وما يتعلق به",["منفذ بالشرع للأحكام ... له نيابة عن الإمام","واستحسنت في حقه الجزاله ... وشرطه التكليف والعداله","وأن يكون ذكرا حرا سلم ... من فقد رؤية وسمع وكلم","ويستحب العلم فيه والورع ... مع كونه الأصول للفقه جمع","وحيث لاق للقضاء يقعد ... وفي البلاد يستحب المسجد"],[]],["فصل في معرفة أركان القضاء",["تمييز حال المدعي والمدعى ... عليه جملة القضاء جمعا","فالمدعي من قوله مجرد ... من أصل أو عرف بصدق يشهد","والمدعى عليه من قد عضدا ... مقاله عرف أو أصل شهدا","وقيل من يقول قد كان ادعا ... ولم يكن لمن عليه يدعى","والمدعى فيه له شرطان ... تحقق الدعوى مع البيان","والمدعي مطالب بالبينه ... وحالة العموم فيه بينه","والمدعى عليه باليمين ... في عجز مدع عن التبيين","والحكم في المشهور حيث المدعى ... عليه في الأصول والمال معا","وحيث يلفيه بما في الذمه ... يطلبه وحيث أصل ثمه","وقدم السابق للخصام ... والمدعي للبدء بالكلام","وحيث خصم حال خصم يدعي ... فاصرف ومن يسبق فذاك المدعي","وعند جهل سابق أو مدعي ... من لج إذ ذاك لقرعة دعي"],[]],["فصل في رفع المدعى عليه وما يلحق به",["ومع مخيلة بصدق الطالب ... يرفع بالإرسال غير الغائب","ومن على يسير الأميال يحل ... فالكتب كاف فيه مع أمن السبل","ومع بعد أو مخافة كتب ... لأمثل القوم أن افعل ما يجب","إما بإصلاح أو الإغرام ... أو أزعج المطلوب للخصام","ومن عصى الأمر ولم يحضر طبع ... عليه ما يهمه كي يرتفع","وأجرة العون على صاحب حق ... ومن سواه إن ألد تستحق"],[]],["فصل في مسائل من القضاء",["وليس بالجائز للقاضي إذا ... لم يبد وجه الحكم أن ينفذا","والصلح يستدعي له إن أشكلا ... حكم وإن تعين الحق فلا","ما لم يخف بنافذ الأحكام ... فتنة أو شحنا أولي الأرحام","وخصم إن يعجز عن القاء الحجج ... لموجب لقنها ولا حرج","ومنع الإفتاء للحكام ... في كل ما يرجع للخصام","وفي الشهود يحكم القاضي بما ... يعلم منهم باتفاق العلما","وفي سواهم مالك قد شددا ... في منع حكمه بغير الشهدا","وقول سحنون به اليوم العمل ... فيما عليه مجلس الحكم اشتمل","وعدل إن أدى على ما عنده ... خلافه منع أن يرده","وحقه إنهاء ما في علمه ... لمن سواه شاهدا بحكمه","وعلمه بصدق غير العدل لا ... يبيح أن يقبل ما تحملا","ومن جفا القاضي فالتأديب ... أولى وذا لشاهد مطلوب","وفلتة من ذي مروءة عثر ... في جانب الشاهد مما يغتفر","ومن ألد في الخصام وانتهج ... نهج الفرار عند إتمام الحجج","ينفذ الحكم عليه الحكم ... قطعا لكل ما به يختصم","وغير مستوف لها إن استتر ... لم تنقطع حجته إذا ظهر","لكنما الحكم عليه يمضي ... بعد تلوم له من يقضي"],[]],["فصل في المقال والجواب",["ومن أبى إقرارا أو إنكارا ... لخصمه كلفه إجبارا","فإن تمادى فلطالب قضي ... دون يمين أو بها وذا ارتضي","والكتب يقتضي عليه المدعي ... من خصمه الجواب توقيفا دعي","وما يكون بينا إن لم يجب ... عليه في الحين فالإجبار يجب","وكل ما افتقر للتأمل ... فالحكم نسخه وضرب الأجل","وطالب التأجيل فيها سهلا ... لمقصد يمنعه وقيل لا","ويوجب التقييد للمقال ... تشعب الدعوى وعظم المال","لأنه أضبط للأحكام ... ولانحصار ناشئ الخصام","وحيثما الأمر خفيف بين ... فالترك للتقييد مما يحسن","فرب قول كان بالخطاب ... أقرب للفهم من الكتاب"],[]],["فصل في الآجال",["ولاجتهاد الحاكم الآجال ... موكولة حيث لها استعمال","وبثلاثة من الأيام ... أجل في بعض من الأحكام","كمثل إحضار الشفيع للثمن ... والمدعي النسيان إن طال الزمن","والمدعي أن له ما يدفع ... به يمينا أمرها مستبشع","ومثبت دينا لمديان وفي ... إخلاء ما كالربع ذلك اقتفي","وشرطه ثبوت الاستحقاق ... برسم الإعذار فيه باقي","وفي سوى أصل له ثمانيه ... ونصفها لستة مواليه","ثم ثلاثة لذاك تتبع ... تلوما وأصله تمتعوا","وفي الأصول وفي الإرث المعتبر ... من عدد الأيام خمسة عشر","ثم تلي أربعة تستقدم ... بضعفها ثم يلي التلوم","وفي أصول إرث أو سواه ... ثلاثة الأشهر منتهاه","لكن مع ادعاء بعد البينه ... ومثله حائز ملك سكنه","مع حجة قوية له متى ... أثبته لنفسه من أثبتا","وبيع ملك لقضاء دين ... قد أجلوا فيه إلى شهرين","وحل عقد شهر التأجيل ... فيه وذا عندهم المقبول","وتجمع الآجال والتفصيل ... في وقتنا هذا هو المعمول"],[]],["فصل في الإعذار",["وقبل حكم يثبت الإعذار ... بشاهدي عدل وذا المختار","وشاهد الإعذار غير معمل ... في شأنه الإعذار للتسلسل","ولا الذي وجهه القاضي إلى ... ما كان كالتحليف منه بدلا","ولا الذي بين يديه قد شهد ... ولا اللفيف في القسامة اعتمد","ولا الكثير فيهم العدول ... والخلف في جميعها منقول"],[]],["فصل في خطاب القضاة وما يتعلق به",["ثم الخطاب للرسوم إن طلب ... حتم على القاضي وإلا لم يجب","والعمل اليوم على قبول ما ... خاطبه قاض بمثل: أعلما","وليس يغني كتب قاض كاكتفى ... عن الخطاب والمزيد قد كفى","وإنما الخطاب مثل إعلما ... إذ معلما به اقتضى ومعلما","وإن يمت مخاطب أو عزلا ... رد خطابه سوى ما سجلا","واعتمد القبول بعض من مضى ... ومعلم يخلفه والي القضا","والحكم العدل على قضائه ... خطابه لابد من إمضائه","وفي الأداء عند قاض حل في ... غير محل حكمه الخلف اقتفي","ومنعه فيه الخطاب المرتضى ... وسوغ التعريف بعض من مضى","ويثبت القاضي على المحو وما ... أشبهه الرسم على ما سلما","وعندما ينفذ حكم وطلب ... تسجيله فإنه أمر يجب","وما على القاضي جناح لا ولا ... من حرج إن ابتداء فعلا","وساغ مع سؤاله تسجيل ما ... لم يواقع النزاع فيه كلما","وسائل التعجيز ممن قد قضى ... يمضى له في كل شيء بالقضا","إلا ادعاء حبس أو طلاق ... أو نسب أو دم أو عتاق","ثم على ذا القول ليس يلتفت ... لما يقال بعد تعجيز: ثبت"],[]],["باب الشهود وأنواع الشهادات وما يتعلق بذلك",["وشاهد صفته المرعيه ... عدالة تيقظ حريه","والعدل من يجتنب الكبائرا ... ويتقي في الغالب الصغائرا","وما أبيح وهو في العيان ... يقدح في مروءة الإنسان","فالعدل ذو التبريز ليس يقدح ... فيه سوى عداوة تستوضح","وغير ذي التبريز قد يجرح ... بغيرها من كل ما يستقبح","ومن عليه وسم خير قد ظهر ... زكي إلا في ضرورة السفر","ومن بعكس حاله فلا غنى ... عن أن يزكي والذي قد أعلنا","بحالة الجرح فليس تقبل ... له شهادة ولا يعدل","وإن يكن مجهول حال زكيا ... وشبهة توجب فيما ادعيا","ومطلقا معروف عين عدلا ... والعكس حاضرا وإن غاب فلا","وشاهد تعديله باثنين ... كذاك تجريح مبرزين","والفحص من تلقاء قاض قنعا ... فيه بواحد في الأمرين معا","ومن يزكي فليقل عدل رضا ... وبعضهم يجيز أن يبعضا","وثابت الجرح مقدم على ... ثابت تعديل إذا ما اعتدلا","وطالب التجديد للتعديل مع ... مضي مدة فالأولى يتبع","ولأخيه يشهد المبرز ... إلا بما التهمة فيه تبرز","والأب لابنه وعكسه منع ... وفي ابن زوجة وعكس ذا اتبع","ووالدي زوجة أو زوجة أب ... وحيثما التهمة حالها غلب","كحالة العدو والظنين ... والخصم والوصي والمدين","وساغ أن يشهد الإبن في محل ... مع أبيه وبه جرى العمل","وزمن الأداء لا التحمل ... صح اعتباره لمقتض جلي"],[]],["فصل",["في مسائل من الشهادات</span>","ويشهد الشاهد بالإقرار ... من غير إشهاد على المختار","بشرط أن يستوعب الكلاما ... من المقر البدء والتماما","وما به قد وقعت شهاده ... وطلب العود فلا إعاده","وشاهد برز خطه عرف ... نسي ما ضمنه فيما سلف","لابد من أدائه بذلك ... إلا مع استرابة هنالك","والحكم في القاضي كمثل الشاهد ... وقيل بالفرق لمعنى زائد","وخط عدل مات أو غاب اكتفي ... فيه بعدلين وفي المال اقتفي","والحبس إن يقدم وقيل يعتمل ... في كل شيء وبه جرى العمل","كذاك في الغيبة مطلقا وفي ... مسافة القصر أجيز فاعرف","وكاتب بخطه ما شاءه ... ومات بعد أو أبى إمضاءه","يثبت خطه ويمضي ما اقتضى ... دون يمين وبذا اليوم القضا","وامتنع النقصان والزياده ... إلا لمن برز في الشهاده","وراجع عنها قبوله اعتبر ... ما الحكم لم يمض وإن لم يعتذر","وإن مضى الحكم فلا واختلفا ... في غرمه لما بها قد أتلفا","وشاهد الزور اتفاقا يغرمه ... في كل حال والعقاب يلزمه"],[]],["فصل",["</span></span> في أنواع الشهادات","ثم الشهادة لدى الأداء ... جملتها خمس بالاستقراء","تختص أولاها على التعيين ... أن توجب الحق بلا يمين","ففي الزنا من الذكور أربعه ... وما عدا الزنا ففي اثنين سعه","ورجل بامرأتين يعتضد ... في كل ما يرجع للمال اعتمد","وفي اثنتين حيث لا يطلع ... إلا النساء كالمحيض مقنع","وواحد يجزئ في باب الخبر ... واثنان أولى عند كل ذي نظر","وبشاهدة من الصبيان في ... جرح وقتل بينهم قد اكتفي","وشرطها التمييز والذكوره ... والإتفاق في وقوع الصوره","من قبل أن يفترقوا أو يدخلا ... فيهم كبير خوف أن يبدلا","فصل","ثانية توجب حقا مع قسم ... في المال أو ما آل للمال تؤم","شهادة العدل لمن أقامه ... وامرأتان قامتا مقامه","وهاهنا عن شاهد قد يغني ... إرخاء ستر واحتياز رهن","واليد مع مجرد الدعوى أو ان ... تكافأت بينتان فاستبن","والمدعى عليه يأبى القسما ... وفي سوى ذلك خلف علما","ولا يمين مع نكول المدعي ... بعد ويقضى بسقوط ما ادعي","وغالب الظن به شهاده ... بحيث لا يصح قطع عاده"],[]],["فصل في التوقيف",["ثالثة لا توجب الحق نعم ... توجب توقيفا به حكم الحكم","وهي شهادة بقطع ارتضي ... وبقي الاعذار فيما تقتضي","وحيث توقيف من المطلوب ... فلا غنى عن أجل مضروب","ووقف ما كالدور غلق مع أجل ... لنقل ما فيها به صح العمل","وما له كالفرن خرج والرحا ... ففيه توقيف الخراج وضحا","وهو في الأرض المنع من أن تعمرا ... والحظ يكرى ويوقف الكرا","قيل جميعا أو بقدر ما يجب ... للحظ من ذاك والأول انتخب","وشاهد عدل به الأصل وقف ... ولا يزال من يد بها ألف","وباتفاق وقف ما يفاد ... منه إذا ما أمن الفساد","وحيثما يكون حال البينه ... في حق من يحكم غير بينه","يوقف الفائد لا الأصول ... بقدر ما يستكمل التعديل","وكل شيء يسرع الفساد له ... وقف لا لأن يرى قد دخله","والحكم بيعه وتوقيف الثمن ... إن خيف في التعديل من طول الزمن","والمدعي كالعبد والنشدان ... ثبوته قام به البرهان","أو السماع أن عبده أبق ... إن طلب التوقيف فهو مستحق","لخمسة أو فوقها يسيرا ... حيث ادعى بينة حضورا","وإن تكن بعيدة فالمدعى ... عليه ما القسم عنه ارتفعا","كذاك مع عدل بنشدان شهد ... وبعد باقيهم يمينه ترد"],[]],["فصل",["رابعة ما تلزم اليمينا ... لا الحق لكن للمطالبينا","شهادة العدل أو اثنتين في ... طلاق أو عتاق أو قذف يفي","وتوقف الزوجة ثم إن نكل ... زوج فسجن ولعام العمل","وقيل للزوجة إذ يدين ... تمنع نفسها ولا تزين","فصل","خامسة ليس عليها عمل ... وهي الشهادة التي لا تقبل","كشاهد الزور والإبن للأب ... وما جرى مجراهما مما أبي"],[]],["فصل في شهادة السماع",["وأعملت شهادة السماع ... في الحمل والنكاح والرضاع","والحيض والميراث والميلاد ... وحال إسلام أو ارتداد","والجرح والتعديل والولاء ... والرشد والتسفيه والإيصاء","وفي تملك لملك بيد ... يقام فيه بعد طول المدد","وحبس من جاز من السنينا ... عليه ما يناهز العشرينا","وعزل حاكم وفي تقديمه ... وضرر الزوجين من تتميمه","وشرطها استعاضة بحيث لا ... يحصر من عنه السماع نقلا","مع السلامة من ارتياب ... يفضي إلى تغليط وإكذاب","ويكتفى فيها بعدلين على ... ما تابع الناس عليه العملا"],[]],["فصل في مسائل من الشهادات",["ومن لطالب بحق شهدا ... ولم يحقق عند ذاك العددا","فمالك عنه به قولان ... للحكم في ذاك مبينان","إلغاؤها كأنها لم تذكر ... وترفع الدعوى يمين المنكر","أو يلزم المطلوب أن يقرا ... ثم يؤدي ما به أقرا","بعد يمينه وإن تجنبا ... تعيينا أو عين والحلف أبى","كلف من يطلبه التعيينا ... وهو له إن أعمل اليمينا","وإن أبى أو قال لست أعرف ... بطل حقه وذاك الأعرف","وما على المطلوب إجبار إذا ... ما شهدوا في أصل ملك هكذا","ومنكر للخصم ما ادعاه ... أثبت بعد أنه قضاه","ليس على شهود من عمل ... لكونه كذبهم في الأول","وفي ذوي عدل يعارضان ... مبرزا أتى لهم قولان","وبالشهيدين مطرف قضى ... والحلف والإعدال أصبغ ارتضى","وقدم التاريخ ترجيح قبل ... لا مع يد والعكس عن بعض نقل","وإنما يكون ذاك عندما ... لا يمكن الجمع لنا بينهما","والشيء يدعيه شخصان معا ... ولا يد ولا شهيد يدعى","يقسم ما بينهما بعد القسم ... وذاك حكم في التساوي ملتزم","في بينات أو نكول أو يد ... والقول قول ذي يد منفرد","وهو لمن أقام فيه البينه ... وحالة الأعدل منها بينه"],[]],["باب اليمين وما يتعلق بها",["في ربع دينار فأعلى تقتضى ... في مسجد الجمع اليمين بالقضا","وما له بال ففيه يخرج ... إليه ليلا غير من تبرج","وقائما مستقبلا يكون ... من استحقت عنده اليمين","وهي وإن تعددت في الأعرف ... على وفاق نية المستحلف","وما يقل حيث كان يحلف ... فيه وبالله يكون الحلف","وبعضهم يزيد لليهودي ... منزل التوراة للتشديد","كما يزيد فيه للتثقيل ... على النصارى منزل الإنجيل","وجملة الكفار يحلفونا ... أيمانهم حيث يعظمونا","وما كمثل الدم واللعان ... فيه تحري الوقت والمكان","وهي يمين تهمة أو القضا ... أو منكر أو مع شاهد رضا","وتهمة إن قويت بها تجب ... يمين متهوم وليست تنقلب","وللتي بها القضا وجوب ... في حق من يعدم أو يغيب","ولا تعاد هذه اليمين ... بعد وإن مر عليها حين","ولليمين أيما إعمال ... فيما يكون من دعاوي المال","إلا بما عد من التبرع ... ما لم يكن في الحال عند المدعي","وفي الإقالة ابن عتاب يرى ... وجوبها بشبهة معتبرا","وهذه اليمين حيث توجب ... يسوغ قلبها وما إن تقلب","ومثبت لنفسه ومن نفى ... عنها على البتات يبدي الحلفا","ومثبت لغيره ذاك اقتفى ... وإن نفى فالنفي للعلم كفى","والبالغ السفيه بان حقه ... يحلف مع عدل ويستحقه","وترجأ اليمين حقت للقضا ... لغير بالغ وحقه اقتضى","وحيث عدل للصغير شهدا ... بحقه وخصمه قد جحدا","يحلف منكر وحق وقفا ... إلى مصير خصمه مكلفا","وحيث يبدي المنكر النكولا ... بلغ محجور به المأمولا","والبكر مع شاهدها تحلف ... وفي ادعاء الوطء أيضا تحلف","وفي سوى المشهور يحلف الأب ... عن ابنه وحلف الابن مذهب"],[]],["باب الرهن وما يتعلق به",["الرهن توثيق بحق المرتهن ... وإن حوى قابل غيبة ضمن","ما لم تقم له عليه بينه ... لما جرى في شأنه معينه","وإن يكن عند أمين وقفا ... فلا ضمان فيه مهما تلفا","والحوز من تمامه وإن حصل ... ولو معارا عند راهن بطل","والعقد فيه لمساقاة وما ... أشبهها حوز وإن تقدما","والشرط أن يكون ما يرتهن ... مما استيفاء حق يمكن","فخارج كالخمر باتفاق ... وداخل كالعبد ذي الإباق","وجاز في الرهن اشتراط المنفعه ... إلا في الأشجار فكل منعه","إلا إذا النفع لعام عينا ... والبدو للصلاح قد تبينا","وفي الذي الدين به من سلف ... وفي التي وقت اقتضائها خفي","وبجواز بيع محدود الأجل ... من غير إذن راهن جرى العمل","مع جعله ذاك له ولم يحن ... دين ولا بعقدة الأصل قرن","وجاز رهن العين حيث يطبع ... عليه أو عند أمين يوضع","والرهن للمشاع مع من رهنا ... قبض جميعه له تعينا","ومع غير راهن يكفيه أن ... يحل فيه كحلول من رهن","والرهن محبوس بباقي ما وقع ... فيه ولا يرد قدر ما اندفع","وشرط ملك الرهن حيث لا يقع ... إنصافه من حقه النهي يقع"],[]],["فصل في اختلاف المتراهنين",["وفي اختلاف راهن ومرتهن ... في عين رهن كان في حق رهن","القول قول راهن إن صدقا ... مقاله شاهد حال مطلقا","كأن يكون الحق قدره مائه ... وقيمة الرهن لعشر مبدئه","والقول حيث يدعي من ارتهن ... حلول وقت الرهن قول من رهن","وفي كثوب خلق ويدعي ... جدته الراهن عكس ذا وعي","إلا إذا خرج عما يشبه ... في ذا وذا فالعكس لا يشتبه"],[]],["باب في الضمان وما يتعلق به",["وسمي الضامن بالحميل ... كذاك بالزعيم والكفيل","وهو من المعروف فالمنع اقتضى ... من أخذه أجرا به أو عوضا","والحكم ذا حيث اشتراط من ضمن ... حطا من المضمون عمن قد ضمن","وباشتراك واستواء في العدد ... تضامن خفف فيه أن ورد","وصح من أهل التبرعات ... وثلث من يمنع كالزوجات","وهو بوجه أو بمال جار ... والأخذ منه أو على الخيار","ولا اعتبار برضا من ضمنا ... إذ قد يؤدى دين من لا أذنا","ويسقط الضمان في فساد ... أصل الذي فيه الضمان باد","وهو بما عين للمعين ... وهو بمال حيث لم يعين","وإن ضمان الوجه جاء مجملا ... الحكم أن المال قد تحملا","وجائز ضمان ما تأجلا ... معجلا وعاجل مؤجلا","وما على الحميل غرم ما حمل ... إن مات مضمون ولم يحن أجل","ويأخذ الضامن من مضمونه ... ثابت ما أداه من ديونه","والشاهد العدل لقائم بحق ... إعطاء مطلوب به الضامن حق","وضامن الوجه على من أنكرا ... دعوى امرئ خشية أن لا يحضرا","من بعد تأجيل لهذا المدعي ... بقدر ما استحق فيما يدعي","وقيل إن لم يلف من يضمنه ... للخصم لازمه ولا يسجنه","وأشهب بضامن الوجه قضى ... عليه حتما وبقوله القضا","ويبرأ الحميل بالوجه متى ... أحضر مضمونا لخصم ميتا","وأخروا السائل للإرجاء ... كاليوم عند الحكم بالأداء","إن جاء في الحال بضامن وإن ... لم يأت بالحميل بالمال سجن"],[]],["باب الوكالة وما يتعلق بها",["يجوز توكيل لمن تصرفا ... في ماله لمن بذاك اتصفا","ومنع التوكيل للذمي ... وليس أن وكل بالمرضي","ومن على قبض صبيا قدما ... فقبضه براءة للغرما","وجاز للمطلوب أن يوكلا ... ومنع سحنون له قد نقلا","وحيثما التوكيل بالإطلاق ... فذالك التفويض باتفاق","وليس يمضي غير ما فيه نظر ... إلا بنص في العموم معتبر","وذا له تقديم من يراه ... بمثله أو بعض ما اقتضاه","ومن على مخصص وكل لم ... يقدم إلا إن به الجعل حكم","وما من التوكيل لاثنين فما ... زاد من الممنوع عند العلما","والنقص للإقرار والإنكار من ... توكيل الإختصام بالرد قمن","وحيث الاقرار أتى بمعزل ... عن الخصام فهو غير معمل","ومن على خصومة معينه ... توكيله فالطول لن يوهنه","وإن يكن قدم للمخاصمه ... وتم ما أراد مع من خاصمه","ورام أن ينشئ أخرى فله ... ذاك إذا أطلق من وكله","ولم يجز عليه نصف عام ... من زمن التوكيل للخصام","وموت من وكل أو وكيل ... يبطل ما كان من التوكيل","وليس من وكله موكل ... بموت من وكله ينعزل","والعزل للوكيل والموكل ... منه يحق بوفاة الأول","وما لمن حضر في الجدال ... ثلاث مرات من انعزال","إلا لعذر مرض أو لسفر ... ومثله موكل ذاك حضر","ومن له موكل وعزله ... لخصمه إن شاء أن يوكله","وكل من على مبيع وكلا ... كان له القبض إذا ما أغفلا","وغائب ينوب في القيام ... عنه أب وابن وفي الخصام","وجائز إثبات غير الأجنبي ... لمن يغيب واختصامه أبي"],[]],["فصل في تداعي الموكل والوكيل",["وإن وكيل ادعى إقباض من ... وكله ما حاز فهو مؤتمن","مع طول مدة وإن يكن مضى ... شهر يصدق مع يمين تقتضى","وإن يكن بالفور الإنكار له ... فالقول مع حلف لمن وكله","وقيل إن القول للوكيل ... مع اليمين دون ما تفصيل","وقيل إن أنكر بعد حين ... فهو مصدق بلا يمين","وإن يمر الزمن القليل ... فمع يمين قوله مقبول","وقيل بل يختص بالمفوض ... إليه ذا الحكم لفرق مقتضي","ومن له وكالة معينه ... يغرم إلا أن يقيم البينه","والزوج للزوجة كالموكل ... فيما من القبض لما باعت يلي","وموت زوج أو وكيل إن عرض ... من غير دفع ما بتحقيق قبض","من ماله يأخذ ذاك قائم ... بالفور والعكس لعكس لازم"],[]],["باب الصلح وما يتعلق به",["والصلح جائز بالاتفاق ... لكنه ليس على الإطلاق","وهو كمثل البيع في الإقرار ... كذاك للجمهور في الإنكار","فجائز في البيع جاز مطلقا ... فيه وما اتقي بيعا يتقى","كالصلح بالفضة أو بالذهب ... تفاضلا أو بتأخر أبي","والصلح بالمطعوم في المطعوم ... نسيئة رد على العموم","والوضع من دين على التعجيل ... أو المزيد فيه للتأجيل","والجمع في الصلح لبيع وسلف ... وما أبان غررا بذا اتصف","والصلح بالطعام قبل القبض ... من ذمة فذاك غير مرضي","وإن يكن يقبض من أمانه ... فحالة الجواز مستبانه"],[]],["فصل",["وللأب الصلح على المحجور ... ولو بدون حقه المأثور","إن خشي الفوت على جميع ما ... هو به يطلب من قد خصما","والبكر وحدها تخص ههنا ... بعفوه عن مهرها قبل البنا","وللوصي الصلح عمن قد حجر ... يجوز إلا مع غبن أو ضرر","ولا يجوز نقض صلح أبرما ... وإن تراضيا وجبرا ألزما","وينقض الواقع في الإنكار ... إن عاد منكر إلى الإقرار","والتركات ما تكون الصلح ... مع علم مقدار لها يصح","ولا يجوز الصلح باقتسام ما ... في ذمة وإن أقر الغرما","والزرع قبل ذروه والثمر ... ما دام مبقى في رؤوس الشجر","ولا بإعطاء من الوراث ... للعين في الكالئ والميراث","وحيث لا عين ولا دين ولا ... كالئ ساغ ما من إرث بذلا","وإن يفت ما الصلح فيه يطلب ... لم يجز إلا مع قبض يجب","وجائز تحلل فيما ادعي ... ولم تقم بينة للمدعي","والصلح في الكالئ حيث حلا ... بالصرف في العين لزوج حلا"],[]],["باب النكاح وما يتعلق به",["وباعتبار الناكح النكاح ... واجب أو مندوب أو مباح","والمهر والصيغة والزوجان ... ثم الولي جملة الأركان","وفي الدخول الختم في الإشهاد ... وهو مكمل في الانعقاد","فالصيغة النطق بما كأنكحا ... من مقتض تأبدا مستوضحا","وربع دينار أقل المصدق ... وليس للأكثر حد ما ارتقي","أو ما به قوم أو دراهم ... ثلاثة فهي له تقاوم","وقدرها بالدرهم السبعيني ... نحو من العشرين في التبيين","وينبغي في ذاك الاحتياط ... بخمسة بقدرها تناط","ومنه ما سمي أو ما فوضا ... فيه وحتما للدخول فرضا","وكل ما يصح ملكا يمهر ... إلا إذا ما كان فيه غرر","والمهر والصداق ما قد أصدقا ... وفي الكتاب بالمجاز أطلقا","ويكره النكاح بالمؤجل ... إلا إذا كان مع معجل","وأمد الكوالئ المعينه ... ستة أشهر لعشرين سنه","بحسب المهر في المقدار ... ونسبة الأزواج والأقدار"],[]],["فصل في الأولياء وما يترتب على الولاية",["وعاقد يكون حر ذكرا ... مكلفا والقرب فيه اعتبرا","والسبق للمالك فابن فأب ... فالأخ فابنه فجد النسب","فالأقربين بعد بالترتيب ... بحسب الدنو في التعصيب","وللوصي العقد قبل الأوليا ... وقيل بعدهم وما أن رضيا","وبعض استحب للوصي ... أن يسند العقد إلى الولي","والمرأة الوصي ليست تعقد ... إلا بتقديم امرئ يعتمد","والعبد والمحجور مهما نكحا ... بغير إذن فانفساخ وضحا","وربع دينار لها بما استحل ... منها إن ابتنى وذا به العمل","وإن يمت زوج فالإرث هدر ... والعكس للحاجر فيه النظر","وعاقد على ابنه حال الصغر ... على شروط مقتضاة بالنظر","إن ابنه بعد البلوغ دخلا ... مع علمه يلزمه ما حملا","وحيث لم يبلغ وإن بنى فما ... يلزمه شيء وهبه علما","والحل بالفسخ بلا طلاق ... إن رد ذاك وبلا صداق"],[]],["فصل فيمن له الإجبار وما يتعلق به",["ثيوبة النكاح والملك معا ... للأب الإجبار بها قد منعا","كما له ذلك في صغار ... بناته وبالغ الأبكار","ويستحب إذنها والسيد ... بالجبر مطلقا له تفرد","والأب إن زوجها من عبد ... فهو متى أجبر ذو تعد","وكالأب الوصي فيما جعلا ... أب له مسوغ ما فعلا","وحيثما زوج بكرا غير الأب ... فمع بلوغ بعد إثبات السبب","وحيثما العقد لقاض ولي ... فمع كفء بصداق المثل","وتأذن الثيب بالإفصاح ... والصمت إذن البكر في النكاح","واستنطقت لزائد في العقد ... كقبض عرض أو كزوج عبد","وثيب بعارض كالبكر ... وبالحرام الخلف فيها يجري","كواقع قبل البلوغ الوارد ... وكالصحيح ما بعقد فاسد","وإن يرشدها الوصي ما أبي ... فيها ولاية النكاح كالأب"],[]],["فصل في حكم فاسد النكاح وما يتعلق به",["وفاسد النكاح مهما وقعا ... فالفسخ فيه أو تلاف شرعا","فما فساده يخص عقده ... ففسخه قبل البنا وبعده","وما فساده من الصداق ... فهو بمهر المثل بعد باق","وحيث درء الحد يلحق الولد ... في كل ما من النكاح قد فسد","وللتي كان بها استمتاع ... صداقها ليس له امتناع","والعقد للنكاح في السر اجتنب ... ولو بالاستكتام والفسخ يجب","والبضع بالبضع هو الشغار ... وعقده ليس له قرار","وأجل الكالئ مهما أغفلا ... قبل البناء الفسخ فيه أعملا","وما ينافي العقد ليس يجعل ... شرطا وغيره بطوع يقبل","ويفسد النكاح بالإمتاع في ... عقدته وهو على الطوع اقتفي"],[]],["فصل في مسائل من النكاح",["والعبد والمرأة حيث وصيا ... وعقدا على صبي أمضيا","والأب لا يقضي اتساع حاله ... تجهيزه لابنته من ماله","وبسوى الصداق ليس يلزم ... تجهز الثيب من يحكم","وأشهر القولين أن تجهزا ... له بكالئ لها قد حوزا","وللوصي ينبغي وللأب ... تشويرها بمالها والثيب","وزائد في المهر بعد العقد لا ... يسقط عما زاده إن دخلا","ونصفه يحق بالطلاق ... من قبل الإبتناء كالصداق","وموته للمنع منه مقتض ... فإنه كهبة لم تقبض","وإن أتى الضمان بالمهر على ... إطلاقه فالحمل صح مجملا","ونحلة ليس لها افتقار ... إلى حيازة وذا المختار","وينفذ المنحول للصغير مع ... أخيه في المشاع إن موت وقع","ومع طلاق قبل الابتناء ... تثبت والفسخ مع البناء","والخلف فيها مع وقوع الفسخ في ... تناكح قبل البناء فاعرف"],[]],["فصل في تداعي الزوجين وما يلحق به",["الزوج والزوجة مهما اختلفا ... في قدر مهر والنكاح عرفا","فإن يكن ذلك من قبل البنا ... فالقول للزوجة قد تعينا","مع اليمين إن تكن لم تحجر ... وعاقد يحجرها بها حري","وبعد ذا يحلف زوج أنكرا ... ثم يكون بعدها مخيرا","في دفع ما كان عليه القسم ... أو الفراق دون شيء يلزم","وإن تراضيا على النكاح ... ففي الأصح الرفع للجناح","وفي انفساخ حيث يفقد الرضا ... وبطلقة واحدة جرى القضا","وتأخذ الزوجة مع نكوله ... ما يقتضيه الحلف في حلوله","والحكم في نكول كل منهما ... بما به بعد اليمين حكما","وقيل بل نكوله مصدق ... لما ادعته زوجة محقق","وحيثما ادعي ما قد ينكر ... تردد الإمام فيه يؤثر","فقال يحلفان والنكاح ... بينهما الفسخ له يتاح","وجعل القول لمن جاء بما ... يشبه وارتضاه بعض العلما","والنوع والوصف إذا ما اختلفا ... فيه للاختلاف في القدر اقتفى","والقول قول الزوج فيما عينا ... من قدره مع حلفه بعد البنا","وتحلف الزوجة إن لم يحلف ... وتقتضي ما عينت بالحلف","وإن هما تحالفا في نوع ما ... أصدق ما كان فحلفا ألزما","وفي الأصح يثبت النكاح ... ومهر مثلها لها مباح"],[]],["فصل في الاختلاف في القبض",["وإن هما قبل البناء اختلفا ... في القبض للنقد الذي قد وصفا","فالقول للزوجة واليمين ... أو للذي في حجره تكون","والقول قول الزوج بعد ما بنى ... ويدعي الدفع لها قبل البنا","وهو لها فيما ادعى من بعد أن ... بنى بها والعرف رعيه حسن","والقول واليمين للذي ابتنى ... في دفعه الكالئ قبل الإبتنا","إن كان قد حل وفي الذي يحل ... بعد بنائه لها القول جعل","ثم لها امتناعها أن يدخلا ... أو تقبض الحائن مما أجلا"],[]],["فصل فيما يهديه الزوج ثم يقع الطلاق",["وكل ما يرسله الزوج إلى ... زوجته من الثياب والحلى","فإن يكن هدية سماها ... فلا يسوغ أخذه إياها","إلا بفسخ قبل أن يبتنيا ... فإنه مستخلص ما بقيا","وإن يكن عارية وأشهدا ... من قبل سرا فله ما وجدا","ومدع إرسالها كي تحتسب ... من مهرها الحلف عليه قد وجب","ثم لها الخيار في صرف وفي ... إمساكها من الصداق فاعرف","ومدعي الإرسال للثواب ... شاهده العرف بلا ارتياب","وشرط كسوة من المحظور ... للزوج في العقد على المشهور"],[]],["فصل في الاختلاف في الشوار المورد بيت البناء",["والأب إن أورد بيت من بنى ... ببنته البكر شوار الابتنا","وقام يدعي إعارة لما ... زاد على نقد إليه سلما","فالقول قوله بغير بينه ... ما لم يطل بعد البنا فوق السنه","وإن يكن بما أعار أشهدا ... قبل الدخول فله ما وجدا","وفي سوى البكر ومن غير أب ... قبول قول دون إشهاد أبي","ولا ضمان في سوى ما أتلفت ... مالكة لأمرها العلم اقتفت"],[]],["فصل في الاختلاف في متاع البيت",["وإن متاع البيت فيه اختلفا ... ولم تقم بينة فتقتفى","فالقول قول الزوج مع يمين ... فيما به يليق كالسكين","وما يليق بالنساء كالحلي ... فهو لزوجة إذا ما تأتلي","وإن يكن لاق بكل منهما ... مثل الرقيق حلفا واقتسما","ومالك بذاك للزوج قضى ... مع اليمين وبقوله القضا","وهو لمن يحلف مع نكول ... صاحبه من غير ما تفصيل"],[]],["فصل في إثبات الضرر والقيام به وبعث الحكمين",["ويثبت الإضرار بالشهود ... أو بسماع شاع في الوجود","وإن تكن قد خالعت وأثبتت ... إضراره ففي اختلاع رجعت","وباليمين النص في المدونه ... وقال قوم ما اليمين بينه","كذا إذا عدل بالإضرار شهد ... فالرد للخلع مع الحلف اعتمد","لأن ذاك راجع للمال ... وفرقة تمضي بكل حال","وحيثما الزوجة تثبت الضرر ... ولم يكن لها به شرط صدر","قيل لها الطلاق كالملتزم ... وقيل بعد رفعه للحكم","ويزجر القاضي بما يشاؤه ... وبالطلاق إن يعد قضاؤه","وإن ثبوت ضرر تعذرا ... لزوجة ورفعها تكررا","فالحكمان بعد يبعثان ... بينهما بمقتضى القرآن","إن وجدا عدلين من أهلهما ... والبعث من غيرهما إن عدما","وما به قد حكما يمضي ولا ... إعذار للزوجين فيما فعلا"],[]],["فصل في الرضاع",["وكل من تحرم شرعا بالنسب ... فمثلها من الرضاع يجتنب","فإن أقر الزوج بالرضاع ... فهو إلى فسخ النكاح داعي","ويلزم الصداق بالبناء ... ونصفه من قبل الإبتناء","كذاك بالإقرار منهما معا ... لا باعتراف زوجة إن وقعا","ويفسخ النكاح بالعدلين ... بصحة الإرضاع شاهدين","وباثنتين إن يكن قولهما ... من قبل عقد قد فشا وعلما","ورجل وامرأة كذا وفي ... واحدة خلف وفي الأولى اقتفي"],[]],["فصل في عيوب الزوجين وما يراد به",["من الجنون والجذام والبرص ... والداء في الفرج الخيار يقتنص","بعد ثبوت العيب أو إقرار ... به ورفع الأمر في المختار","وداء فرج الزوج بالقضاء ... كالجب والعنة والخصاء","وذاك لا يرجى له زوال ... فليس في الحكم به إمهال","وحيث عيب الزوج باعتراض ... أو برص وقيم عند القاضي","أجله إلى تمام عام ... كذاك في الجنون والجذام","وبعد ذا يحكم بالطلاق ... إن عدم البرء على الإطلاق","والعبد في الأصح كالأحرار ... وقيل بالتشطير كالظهار","وكالرجال أجل النساء ... في هذه الثلاثة الأدواء","وفي سواها لا يكون الأجل ... لهن إلا ما يرى المؤجل","ويمنع المبروص والمجذوم من ... بنائه وذو الجنون فاستبن","وذو اعتراض وحده لن يمنعا ... وهو مصدق إذا ما نوزعا","وإن يقل وطئت أثناء الأمد ... فقوله مع اليمين معتمد","وتمنع الإنفاق من لم تدخل ... إن طلبته في خلال الأجل","والعيب في الرجال من قبل البنا ... وبعده الرد به تعينا","إلا اعتراضا كان بعد ما دخل ... والوطء منه هبه مرة حصل","وبالقديم الزوج والكثير ... يرد والحادث واليسير","إلا حديث برص منزور ... فلا طلاق منه في المشهور","وزوجة بسابق لعقده ... وهو لزوج آفة من بعده","والرتق داء الفرج في النساء ... كالقرن ثم العفل والإفضاء","ولا ترد من عمى ولا شلل ... ونحوه إلا بشرط يمتثل","والزوج حيث لم يجدها بكرا ... لم يرجع إلا باشتراط عذرا","ما لم يزل عذرتها نكاح ... مكتتم فالرد مستباح","والقول قول الزوج قبل الإبتنا ... في قدم العيب الذي تبينا","والقول بعد في الحدوث قول الأب ... والزوج إذ ذاك بيانه وجب","كذا برد في انتساب ألفيا ... لغية أو مسترقا قضيا"],[]],["فصل في الإيلاء والظهار",["ومن لوطء بيمين منعه ... لزوجة فوق شهور أربعه","فذلك المولي وتأجيل وجب ... له إلى فيئته لما اجتنب","وأجل الإيلاء من يوم الحلف ... وحانث من يوم رفعه ائتنف","ويقع الطلاق حيث لا يفي ... إلا على ذي العذر في التخلف","وعادم للوطء للنساء ... ليس له كالشيخ من إيلاء","وأجل المولي شهور أربعه ... واشترك التارك للوطء معه","في ذاك حيث الترك قصدا للضرر ... من بعد زجر حاكم وما ازدجر","بعد تلوم وفي الظهار ... لمن أبى التكفير ذاك جار","وأجل المظاهر المأثور ... من يوم رفعه هو المشهور","من بعد أن يؤمر بالتكفير ... وهي على الترتيب لا التخيير","كذاك أيضا ما له ظهار ... من لأعلى الوطء له اقتدار","وإن يكن مظاهر أو مولي ... عبدا يؤجل نصف ذا التأجيل","ثم الطلاق في انقضاء الأجل ... بعد تقضي الموجبات الأول","ويملك الرجعة فيما أصدرا ... من فاء في العدة أو من كفرا"],[]],["فصل في اللعان",["وإنما للزوج أن يلتعنا ... بنفي حمل أو برؤية الزنا","مع ادعائه للاستبراء ... وحيضة بينة الإجزاء","ويسجن القاذف حتى يلتعن ... وإن أبى فالحد حكم يقترن","وما بحمل بثبوته يقع ... وقد أتى عن مالك حتى تضع","ويبدأ الزوج بالالتعان ... لدفع حد أربع الأيمان","إثباتا أو نفيا على ما وجبا ... مخمسا بلعنة إن كذبا","وتحلف الزوجة بعد أربعا ... لتدرأ الحد بنفي ما ادعى","تخميسها بغضب إن صدقا ... ثم إذا تم اللعان افترقا","ويسقط الحد وينتفي الولد ... ويحرم العود إلى طول الأمد","والفسخ من بعد اللعان ماض ... دون طلاق وبحكم القاضي","ومكذب لنفسه بعد التحق ... ولده وحد والتحريم حق","وراجع قبل التمام منهما ... يحد والنكاح لن ينفصما","وساكت والحمل حمل بين ... يحد مطلقا ولا يلتعن","ومثله الواطئ بعد الرؤية ... ويلحق الولد حد الفرية","وإن تضع بعد اللعان لأقل ... من ستة الأشهر فالمهر بطل","وليس للتحريم من تأبيد ... إذ النكاح كان كالمفقود"],[]],["باب الطلاق والرجعة وما يتعلق بهما",["من الطلاق الطلقة السنيه ... إن حصلت شروطها المرعيه","وهي الوقوع حال طهر واحده ... من غير مس وارتداف زائده","من ذاك بائن ومنه رجعي ... وما عدا السني فهو بدعي","منه مملك ومنه خلعي ... وذو الثلاث مطلقا ورجعي","ويملك الرجعة في الرجعي ... قبل انقضاء الأمد المرعي","ولا افتقار فيه للصداق ... والإذن والولي باتفاق","وموقع الطلاق دون طهر ... يمنع مع رجوعه بالقهر","وفي المملك خلاف والقضا ... بطلقة بائنة في المرتضى","وبائن كل طلاق أوقعا ... قبل البناء كيفما قد وقعا","وبالثلاث لا تحل إلا ... من بعد زوج للذي تخلى","وهو لحر منتهى الطلاق ... وحكمها ينفذ بالإطلاق","هب أنها بكلمة قد جمعت ... أو طلقة من بعد أخرى وقعت","وموقع ما دونها معدود ... بينهما إن قضي التجديد"],[]],["فصل",["</span></span> في الخلع","والخلع سائغ والإفتداء ... فالإفتداء بالذي تشاء","والخلع باللازم في الصداق ... وحمل أو عدة أو إنفاق","وليس للأب إذا مات الولد ... شيء وذا به القضاء في المدد","والخلع بالإنفاق محدود الأجل ... بعد الرضاع بجوازه العمل","وجاز قولا واحدا حيث التزم ... ذاك وإن مخالع به عدم","وللأب الترك من الصداق ... أو وضعه للبكر في الطلاق"],[]],["فصل",["</span>","ويلزم الطلاق بالتصريح ... وبالكنايات على الصحيح","وينفذ الواقع من سكران ... مختلط كالعتق والأيمان","ومن مريض ومتى من المرض ... مات فللزوجة الإرث مفترض","ما لم يكن بخلع أو تخيير ... أو مرض ليس من المحذور","والخلف في مطلق هزلا وضح ... ثالثها إلا إن الهزل اتضح","ومالك ليس له بملزم ... لمكره في الفعل أو في القسم","فصل","وكل من يمينه باللازمه ... له الثلاث في الأصح لازمه","وقيل بل واحدة رجعيه ... مع جهله وفقده للنيه","وقيل بل بائنة وقيل بل ... جميع الأيمان وما به عمل","والبكر ذات الأب لا تختلع ... إلا بإذن حاجز وتمنع","وجاز إن أب عليها أعمله ... كذا على الثيب بعد الإذن له","وامتنع الخلع على المحجور ... إلا بإذنه على المشهور","والخلع جائز على الأصاغر ... مع أخذ شيء لأب أو حاجر","ومن يطلق زوجة وتختلع ... بولد منه له ويرتجع","ثم يطلقها فحكم الشرع ... أن لا يعود حكم ذاك الخلع","وإن تمت ذات اختلاع وقفا ... من مالها ما فيه للدين وفا","للأمد الذي إليه التزما ... وهو مشارك به للغرما","وموقع الثلاث في الخلع ثبت ... طلاقه والخلع رد إن أبت"],[]],["فصل",["</span>","وموقع الطلاق دون نيه ... بطلقة يفارق الزوجيه","وقيل بل يلزمه أقصاه ... والأول الأظهر لا سواه","وما امرؤ لزوجة يلتزم ... مما زمان عصمة يستلزم","فذا إذا دون الثلاث طلقا ... زال وإن راجع عاد مطلقا","مثل حضانة والإنفاق على ... أولادها ومثل شرط جعلا","كذا جرى العمل في التمتيع ... بأنه يرجع بالرجوع","وشيخنا أبو سعيد فرقا ... بينهما ردا على من سبقا","وقال قد قاس قياسا فاسدا ... من جعل البابين بابا واحدا","لأنه حق له قد أسقطه ... فلا يعود دون أن يشترطه","وذاك لم يسقطه مستوجبه ... فعاد عندما بدا موجبه","والأظهر العود كمن تختلع ... فكل ما تتركه مرتجع","فصل في التداعي في الطلاق","والزوج إن طلق من بعد البنا ... ولادعاء الوطء رد معلنا","فالقول للزوجة وتستحق ... بعد اليمين مهرها الذي يحق","وإن يكن منها نكول بالقسم ... عليه والواجب نصف ما التزم","ويغرم الجميع مهما نكلا ... وإن يكن لا لابتناء قد خلا","فالقول قول زائر وقيل بل ... لزوجة وما عليه من عمل","ومن كسا الزوجة ثم طلقا ... يأخذها مع قرب عهد مطلقا","والأخذ إن مرت لها شهور ... ثلاثة فصاعدا محظور","وإن يكونا اختلفا في الملبس ... فالقول قول زوجة في الأنفس","والقول للزوج بثوب ممتهن ... ولبس ذات الحمل بالحمل اقترن","وحيثما خلفهما في الزمن ... يقال للزوجة فيه بيني","وعجزها يمين زوج يوجب ... وإن أراد قلبها فتقلب","فصل","ومن يطلق طلقة رجعيه ... ثم أراد العود للزوجيه","فالقول للزوجة واليمين ... على انقضاء عدة تبين","ثم له ارتجاعها حيث الكذب ... مستوضح من الزمان المقترب","وما ادعت من ذلك المطلقه ... بالسقط فهي أبدا مصدقه","ولا يطلق العبيد السيد ... إلا الصغير مع شيء يرفد","وكيفما شاء الكبير طلقا ... ومنتهاه طلقتان مطلقا","لكن في الرجعي الأمر بيده ... دون رضا وليها وسيده","والحكم في العبيد كالأحرار ... في غاية الزوجات في المختار","ويتبع الأولاد في استرقاق ... للأم لا للأب بالإطلاق","وكسوة لحرة ونفقه ... عليه والخلف بغير المعتقه","وليس لازما له أن ينفقا ... علة بنيه أعبدا أو عتقا"],[]],["فصل في المراجعة",["وكابتداء ما سوى الرجعي ... في الإذن والصداق والولي","ولا رجوع لمريضة ولا ... بالحمل ستة الشهور وصلا","وزوجة العبد إذا ما عتقت ... واختارت الفراق منه طلقت","بما تشاؤه ومهما عتقا ... فما له من ارتجاع مطلقا"],[]],["فصل في الفسخ",["وفسخ فاسد بلا وفاق ... بطلقة تعد في الطلاق","ومن يمت قبل وقوع الفسخ ... في ذا فما لإرثه من نسخ","وفسخ ما الفساد فيه مجمع ... عليه من غير طلاق يقع","وتلزم العدة باتفاق ... لمبتنى بها على الإطلاق"],[]],["باب النفقات وما يتعلق بها",["ويجب الإنفاق للزوجات ... في كل حالة من الحالات","والفقر شرط الأبوين والولد ... عدم مال واتصال للأمد","ففي الذكور للبلوغ يتصل ... وفي الإناث بالدخول ينفصل","والحكم في الكسوة حكم النفقه ... ومؤن العبد تكون مطلقه","ومنفق على صغير مطلقا ... له الرجوع بالذي قد أنفقا","على أب أو مال الابن وأبي ... إلا بعلم المال أو يسر الأب","ويرجع الوصي مطلقا بما ... ينفقه وما اليمين ألزما","وغير موص يثبت الكفاله ... ومع يمين يستحق ماله"],[]],["فصل في التداعي في النفقة",["ومن يغب عن زوجة ولم يدع ... نفقة لها وبعد أن رجع","ناكرها في قولها للحين ... فالقول قوله مع اليمين","ما لم تكن لأمرها قد رفعت ... قبل إيابه ليقوى ما ادعت","فيرجع القول لها مع الحلف ... والرد لليمين فيهما عرف","وحكم ما على بنيه أنفقت ... كحكم ما لنفسها قد وثقت","فإن يكن قبل المغيب طلقا ... فالقول قولها بذاك مطلقا","إن أعملت في ذلك اليمينا ... وأثبتت حضانة البنينا","فإن يكن مدعيا حال العدم ... طول مغيبه وحاله انبهم","فحالة القدوم لابن القاسم ... مستند لها قضاء الحاكم","ومعسر مع اليمين صدقا ... وموسر دعواه لن تصدقا","وقيل بالحمل على اليسار ... والقول بالتصديق أيضا جاري","وقيل باعتبار وقت السفر ... والحكم باستصحاب حاله حري"],[]],["فصل فيما يجب للمطلقات وغيرهن من الزوجات من النفقة وما يلحق بها",["إسكان مدخول بها إلى انقضا ... عدتها من الطلاق مقتضا","وذات حمل زيدت الإنفاقا ... لوضعها والكسوة اتفاقا","وما لها إن مات حمل من بقا ... واستثن سكنى إن يمت من طلقا","وفي الوفاة تجب السكنى فقد ... في داره أو ما كراءه نقد","وخمسة الأعوام أقصى الحمل ... وستة الأشهر في الأقل","وحال ذات طلقة رجعيه ... في عدة كحالة الزوجيه","من واجب عليه كالإنفاق ... إلا في الاستمتاع بالإطلاق","وحيث لا عدة للمطلقه ... فليس من سكنى ولا من نفقه","وليس للرضيع سكنى بالقضا ... على أبيه والرضاع ما انقضى","ومرضع ليس بذي مال على ... والده ما يستحق جعلا","ومع طلاق أجرة الإرضاع ... إلى تمام مدة الرضاع","وبعدها يبقى الذي يختص به ... حتى يرى سقوطه بموجبه","وإن تكن مع ذاك ذات حمل ... زيدت لها نفقة بالعدل","بعد ثبوته وحيث بالقضا ... تؤخذ وانفش فمنها تقتضى","وإن يكن دفع بلا سلطان ... ففي رجوعه به قولان","ومن له مال ففيه الفرض حق ... وعن أب يسقط كل ما استحق","وكل ما يرجع لافتراض ... موكل إلى اجتهاد القاضي","بحسب الأقوات والأعيان ... والسعر والزمان والمكان"],[]],["فصل في الطلاق بالإعسار بالنفقة وما يلحق بها",["الزوج إن عجز عن إنفاق ... لأجل شهرين ذو استحقاق","بعدهما الطلاق لا من فعله ... وعاجز عن كسوة كمثله","ولاجتهاد الحاكمين يجعل ... في العجز عن هذا وهذا الأجل","وذاك من بعد ثبوت ما يجب ... كمثل عصمة وحال من طلب","وواجد نفقة وما ابتنى ... وعن صداق عجزه تبينا","تأجيله عامان وابن القاسم ... يجعل ذاك لاجتهاد الحاكم","وزوجة الغائب حيث أملت ... فراق زوجها بشهر أجلت","وبانقضاء الأجل الطلاق مع ... يمينها وباختيارها يقع","ومن عن الإخدام عجزه ظهر ... فلا طلاق وبذا الحكم اشتهر"],[]],["فصل في أحكام المفقودين",["وحكم مفقود بأرض الكفر ... في غير حرب حكم من في الأسر","تعميره في المال والطلاق ... ممتنع ما بقي الإنفاق","وكل من ليس له مال حري ... بأن يكون حكمه كالمعسر","وإن يكن في الحرب فالمشهور ... في ماله والزوجة التعمير","وفيه أقوال لهم معينه ... أصحها القول بسبعين سنه","وقد أتى قول بضرب عام ... من حين يأس منه لا القيام","ويقسم المال على مماته ... وزوجة تعتد من وفاته","وذا به القضاء في الأندلس ... لمن مضى فمقتفيهم مؤتس","ومن بأرض المسلمين يفقد ... فأربع من السنين الأمد","وباعتداد الزوجة الحكم جرى ... مبعضا والمال فيه عمرا","وحكم مفقود بأرض الفتن ... في المال والزوجة حكم من فني","مع التلوم لأهل الملحمه ... بقدر ما تنصرف المنهزمه","وإن نأت أماكن الملاحم ... تربص العام لدى ابن القاسم","وأمد العدة فيه إن شهد ... أن قد رأى الشهود فيها من فقد"],[]],["فصل في الحضانة",["الحق للحاضن في الحضانه ... وحال هذا القول مستبانه","لكونه يسقطها فتسقط ... وقيل بالعكس فما إن تسقط","وصرفها إلى النساء أليق ... لأنهن في الأمور أشفق","وكونهن من ذوات الرحم ... شرط لهن وذوات محرم","وهي إلى الإثغار في الذكور ... والاحتلام الحد في المشهور","وفي الإناث للدخول المنتهى ... والأم أولى ثم أمها بها","فأمها فخالة فأم الأب ... ثم أب فأم من له انتسب","فالأخت فالعمة ثم ابنة الأخ ... فابنة أخت فأخ بعد رسخ","والعصبات بعد والوصي ... أحق والسن بها مرعي","وشرطها الصحة والصيانه ... والحرز والتكليف والديانه","وفي الإناث عدم الزوج عدا ... جدا لمحضون لها زوجا غدا","وما سقوطها لعذر قد بدا ... وارتفع العذر تعود أبدا","وهي على المشهور لا تعود إن ... كان سقوطها بتزويج قمن","وحيث بالمحضون سافر الولي ... بقصد الاستيطان والتنقل","فذاك مسقط لحق الحاضنه ... إلا إذا صارت هناك ساكنه","ويمنع الزوجان من إخراج من ... من حين الابتناء معهما سكن","من ولد لواحد أو أم ... وفي سواهم عكس هذا الحكم"],[]],["باب البيوع وما شاكلها",["ما يستجاز بيعه أقسام ... أصول أو عروض أو طعام","أو ذهب أو فضة أو ثمر ... أو حيوان والجميع يذكر","والبيع والشرط الحلال إن وقع ... مؤثرا في ثمن مما امتنع","وكل ما ليس له تأثير ... في ثمن جوازه مأثور","والشرط إن كان حراما بطلا ... به المبيع مطلقا إن جعلا","وجمع بيع مع شركة ومع ... صرف وجعل ونكاح امتنع","ومع مساقاة ومع قراض ... وأشهب الجواز عنه ماض","ونجس صفقته محظوره ... ورخصوا في الزبل للضروره"],[]],["فصل في بيع الأصول",["البيع في الأصول جاز مطلقا ... إلا بشرط في البيوع متقى","بأضرب الأثمان والآجال ... ممن له تصرف في المال","وجائز أن يشترى الهواء ... لأن يقام معه البناء","وما على الجزاف والتكسير ... يباع مفسوخ لدى الجمهور","وآبر من زرع أو من شجر ... لبائع إلا بشرط المشتري","ولا يسوغ باشتراط بعضه ... وإن جرى فلا غنى عن نقضه","وغير ما أبر للمبتاع ... بنفس عقده بلا نزاع","ولا يجوز شرطه للبائع ... والبيع مفسوخ به في الواقع","وفي الثمار عقدها الإبار ... والزرع أن تدركه الأبصار","كذا قليب الأرض للمبتاع ... دون اشتراطه في الابتياع","والماء إن كان يزيد ويقل ... فبيعه لجهله ليس يحل","وشرط إبقاء المبيع بالثمن ... رهنا سوى الأصول بالمنع اقترن","وقيل بالجواز مهما اتفقا ... في وضعه عند أمين مطلقا","وجائز في الدار أن يستثنى ... سكنى بها كسنة أو أدنى","ومشتري الأصل شراؤه الثمر ... قبل الصلاح جائز فيما اشتهر","والزرع في ذلك مثل الشجر ... ولا رجوع إن تصب للمشتري","وبيع ملك غاب جاز بالصفه ... أو رؤية تقدمت أو معرفه","وجاز شرط النقد في المشهور ... ومشتر يضمن للجمهور","والأجنبي جائز منه الشرا ... ملتزم العهدة فيما يشترى"],[]],["فصل في بيع العروض من الثياب وسائر السلع",["بيع العروض بالعروض إن قصد ... تعاوض وحكمه بعد يرد","فإن يكن مبيعها يدا بيد ... فإن ذاك جائز كيف انعقد","وإن يكن مؤجلا وتختلف ... أجناسه فما تفاضل أنف","والجنس من ذاك بجنس للأمد ... ممتنع فيه تفاضل فقد","إلا إذا تختلف المنافع ... وما لبيع قبل قبض مانع","وبيع كل جائز بالمال ... على الحلول وإلى الآجال","ومن يقلب ما يفيت شكله ... لم يضمن إلا حيث لم يؤذن له","والبيع جائز على أن ينتقد ... في موضع أخر إن حد الأمد","وبيع ما يجهل ذاتا بالرضا ... بالثمن البخس أو العالي مضى","وما يباع أنه ياقوته ... أو أنه زجاجة منحوته","ويظهر العكس بكل منهما ... جاز به قيام من تظلما"],[]],["فصل في بيع الطعام",["البيع للطعام بالطعام ... دون تناجز من الحرام","والبيع للصنف بصنفه ورد ... مثلا بمثل مقتضى يدا بيد","والبيع للطعام قبل القبض ... ممتنع ما لم يكن عن قرض","والجنس بالجنس تفاضلا منع ... حيث اقتيات وادخار يجتمع","وغير مقتات ولا مدخر ... يجوز مع تفاضل كالخضر","وفي اختلاف الجنس بالإطلاق ... جاز مع الإنجاز باتفاق","وبيع معلوم بما قد جهلا ... من جنسه تزابن لن يقبلا"],[]],["فصل في بيع النقدين والحلي وشبهه",["والصرف أخذ فضة بذهب ... أو عكسه وما تفاضل أبي","والجنس بالجنس هو المراطله ... بالوزن أو بالعد فالمبادله","والشرط في الصرف تناجز فقط ... ومعه المثل بثان يشترط","وبيع ما حلي مما اتخذا ... بغير جنسه بنقد نفذا","وكل ما الفضة فيه والذهب ... فبالعروض البيع في ذاك وجب"],[]],["فصل في بيع الثمار وما يلحق بها",["بيع الثمار والمقاثي والخضر ... بدو الصلاح فيه شرط معتبر","وحيث لم يبد صلاحها امتنع ... ما لم يكن بالشرط للقطع وقع","وخلفة القصيل ملكه حري ... لبائع إلا بشرط المشتري","ولا يجوز في الثمار الأجل ... إلا بما إثماره متصل","وغائب في الأرض لا يباع ... إلا إذا يحصل الانتفاع","وجائز في ذاك أن يستثنى ... أكثر من نصف له أو أدنى","ودون ثلث إن يكن ما استثني ... بعدد أو كيل أو بوزن","وإن يكن لثمرات عينا ... فمطلقا يسوغ ما تعينا","وفي عصير الكرم يشرى بالذهب ... أو فضة أخذ الطعام يجتنب"],[]],["فصل",["في الجائحة في ذلك</span>","وكل ما لا يستطاع الدفع له ... جائحة مثل الرياح المرسله","والجيش معدود من الجوائح ... كفتنة وكالعدو الكاشح","فإن يكن من عطش ما اتفقا ... فالوضع للثمن فيه مطلقا","وإن تكن من غيره ففي الثمر ... ما بلغ الثلث فأغلى المعتبر","وفي البقول الوضع في الكثير ... وفي الذي قل على المشهور","وألحقوا نوع المقاثي بالثمر ... هنا وما كالياسمين والجزر","والقصب الحلو به قولان ... كورق التوت هما سيان","وكلها البائع ضامن لها ... إن كان ما أجيح قبل الانتها"],[]],["فصل في بيع الرقيق وسائر الحيوان",["بيع الرقيق أصله السلامه ... وحيث لم تذكر فلا ملامه","وهو مبيح للقيام عندما ... يوجد عيب بالمبيع قدما","والعيب إما ذو تعلق حصل ... ثبوته فيما يباع كالشلل","أو ما له تعلق لكنه ... منتقل عنه كمثل الجنه","أو بائن كالزوج والإباق ... فالرد في الجميع بالإطلاق","إلا بأول بما منه ظهر ... لمن يكون بالعيوب ذا بصر","والخلف في الخفي منه والحلف ... يلزم إلا مع تدين عرف","وحيث لا يثبت في الغيب القدم ... كان على البائع في ذاك القسم","وهو على العلم بما يخفى وفي ... غير الخفي الحلف بالبت اقتفي","وفي نكول بائع من اشترى ... يحلف والحلف على ما قرر","وليس في صغيرة مواضعه ... ولا لوخش حيث لا مجامعه","ولا يجوز شرط تعجيل الثمن ... وإن يكن ذاك بطوع فحسن","والبيع مع براءة إن نصت ... على الأصح بالرقيق اختصت","والفسخ إن عيب بدا من حكمه ... مع اعتراف أو ثبوت علمه","ويحلف البائع مع جهل الخفي ... بالعلم والظاهر بالبث حفي","وحيثما نكوله تبدا ... به المبيع لا اليمين ردا","وبعضهم فيها الجواز أطلقا ... وشرطها مكث بملك مطلقا","واليوم واليومان في المركوب ... وشبهه استثني للركوب","ولم يجز في الحيوان كله ... شراؤه على اشتراط حمله","وذات حمل قد تدانى وضعها ... لم يمتنع على الأصح بيعها","كذا المريض في سوى السياق ... يصح بيعه على الإطلاق","والعبد في الإباق مع علم محل ... قراره مما ابتياع فيه حل","والبائع الضامن حتى يقبضا ... وإن تقع إقالة لا ترتضى","وامتنع التفريق للصغار ... من أمهم إلا مع الإثغار","ثم بالإجبار على الجمع القضا ... والخلف إن يكن من الأم الرضا","والحمل عيب قيل بالإطلاق ... وقيل في علية ذي استرقاق","والافتضاض في سوى الوخش الدني ... عيب لها مؤثر في الثمن","والحمل لا يثبت في أقل من ... ثلاثة من الشهور فاستبن","ولا تحرك له يثبت في ... ما دون عدة الوفاة فاعرف","ويثبت العيوب أهل المعرفه ... بها ولا ينظر فيهم لصفه"],[]],["فصل",["واتفقوا أن الكلاب الماشيه ... يجوز بيعها ككلب الباديه","وعندهم قولان في ابتياع ... كلاب الاصطياد والسباع","وبيع ما كالشاة واستثناء ... تلثه فيه الجواز جاء","أو قدر رطلين معا من شاة ... ويجبر الآبي على الذكاة","وليس يعطى فيه للتصحيح ... من غيره لحما على الصحيح","والخلف في الجلد وفي الرأس صدر ... مشهورها الجواز في حال السفر","وفي الضمان إن تفانى أو سلب ... ثالثها في الجلد والرأس يجب"],[]],["فصل في بيع الدين والمقاصة فيه",["مما يجوز البيع بيع الدين ... مسوغ من عرض أو من عين","وإنما يجوز مع حضور من ... أقر بالدين وتعجيل الثمن","وكونه ليس طعام بيع ... وبيعه بغير جنس مرعي","وفي طعام إن يكن من قرض ... يجوز الابتياع قبل القبض","والاقتضاء للديون مختلف ... والحكم قبل أجل لا يختلف","والمثل مطلوب وذو اعتبار ... في الجنس والصفة والمقدار","والعين فيه مع بلوغ أجلا ... صرف وما تشاؤه إن عجلا","وغير عين بعده من سلف ... خذ فيه من معجل ما تصطفي","وإن يكن من سلم بعد الأمد ... فالوصف فيه السمح جائز فقد","ويقتضى الدين من الدين وفي ... عين وعرض وطعام قد يفي","فما يكونان به عينا إلى ... مماثل وذي اختلاف فضلا","فما اختلاف وحلول عمه ... يجوز فيه صرف ما في الذمه","وفي تأخر الذي يماثل ... ما كان أشهب بمنع قائل","وفي اللذين في الحلول اتفقا ... على جواز الانتصاف اتفقا","وذاك في العرضين لا المثلين حل ... بحيث حلا أو توافق الأجل","وفي توافق الطعامين اقتفي ... حيث يكونان معا من سلف","وفي اختلاف لا يجوز إلا ... إن كان كل منهما قد حلا","وإن يكونا من مبيع ووقع ... فيه بالإطلاق اختلاف امتنع","وفي اتفاق أجلي ما اتفقا ... هو لدى أشهب غير متقى","وشرط ما من سلف وبيع ... حلول كل واتفاق النوع","والخلف في تأخر ما كانا ... ثالثها مع سلم قد حانا"],[]],["فصل في الحوالة",["وامنع حوالة بشيء لم يحل ... وبالذي حل بالإطلاق أحل","وبالرضا والعلم من محال ... عليه في المشهور لا تبال","ولا يجوز أن يحال إلا ... فيما يجانس لدين حلا","ولا تحل بأحد النقدين في ... ثانيهما إن القبض اقتفي","وفي الطعام ما إحالة تفي ... إلا إذا كانا معا من سلف","وفي اجتماع سلم وقرض ... يشترط الحلول في ذا القبض"],[]],["فصل في بيع الخيار والثنيا",["بيع الخيار جائز الوقوع ... لأجل يليق بالمبيع","كالشهر في الأصل وبالأيام ... في غيره كالعبد والطعام","وهو بالاشتراط عند العقد ... ولا يجوز فيه شرط النقد","والبيع بالثنيا لفسخ داع ... والخرج بالضمان للمبتاع","ولا كراء فيه هبه لأجل ... أو لا وذا الذي به جرى العمل","والشرح للثنيا رجوع ملك من ... باع إليه عند إحضار الثمن","جاز إن وقع بعد العقد ... طوعا بحد وبغير حد","وحيثما شرط على الطوع جعل ... فالأحسن الكتب بعقد مستقل","والقول قول مدع للطوع ... لا مدعي الشرط بنفس البيع"],[]],["فصل في بيع الفضولي وما يماثله",["وحاضر بيع عليه ماله ... بمجلس قيه السكوت حاله","يلزم ذا البيع وإن أقر من ... باع له بالملك أعطي الثمن","وإن يكن وقت المبيع بائعه ... لنفسه ادعاه وهو سامعه","فما له إن قام أي حين ... في ثمن حق ولا مثمون","وغائب يبلغه ما عمله ... وقام بعد مدة لا شيء له","وغير من في عقدة البيع حضر ... وبالمبيع بائع له أقر","وقام بالفور فذا التخيير في ... إمضائه البيع أو الفسخ اقتفي","وإن يقم من بعد أن مضى زمن ... فالبيع ماض وله أخذ الثمن","إن كان عالما بفعل البائع ... وساكتا لغير عذر مانع","وحاضر لواهب من ماله ... ولم يغير ما رأى من حاله","الحكم منعه القيام بانقضا ... مجلسه إذ صمته عين الرضا","والعتق مطلقا على السواء ... مع هبة والوطء للإماء","والزوجة استفاد زوج مالها ... وسكتت عن طلب لما لها","لها القيام بعد في المنصوص ... والخلف في السكنى على الخصوص","كذاك ما استغله من غير أن ... متع إن مات كمثل ما سكن","فيه خلاف والذي به العمل ... في الموت أخذها كراء ما استغل","وحاضر لقسم متروك له ... عليه دين لم يكن أهمله","لا يمنع القيام بعد إن بقي ... للقسم قدر دينه المحقق","ويقتضي من ذاك حقا ملكه ... بعد اليمين أنه ما تركه"],[]],["فصل في بيع المضغوط وما أشبهه",["ومن يبع في غير حق شرعي ... بالقهر مالا تحت ضغط مرعي","فالبيع إن وقع مردود ومن ... باع يحوز المشترى دون ثمن","والخلف في البيع لشيء مغتصب ... ثالثها جوازه ممن غصب"],[]],["فصل في مسائل من أحكام البيع",["أب على بنيه في وثاق ... حجر له يبيع بالإطلاق","وفعله على السداد يحمل ... وحيث لا رد ابنه ما يفعل","وبيع من وصي للمحجور ... إلا لمقتض من المحظور","وجاز بيع حاضن بشرط أن ... أهمل محضون ولا يعلو الثمن","عشرين دينارا من الشرعي ... فضية وذا على المرضي","وما اشترى المريض أو ما باعا ... إن هو مات يأبى الامتناعا","فإن يكن حابى به فالأجنبي ... من ثلثه يأخذ ما به حبي","وما به الوارث حابى منعا ... وإن يجزه الوارثون اتبعا","وكل ما القاضي يبيع مطلقا ... بيع براءة به تحققا","والخلف فيما باعه الوصي ... أو وارث ومنعه المرضي","إلا بما البيع به يكون ... برسم أن تقضى به الديون"],[]],["فصل [ومن أصم أبكم العقود الخ",["ومن أصم أبكم العقود ... جائزة ويشهد الشهود","بمقتضى إشارة قد أفهمت ... مقصوده وبرضاه أعلمت","فإن يكن مع ذاك أعمى امتنعا ... لفقده الإفهام والفهم معا","كذاك للمجنون والصغير ... يمنع والسكران للجمهور","وذو العمى يجوز الابتياع له ... وبيعه وكل عقد أعمله","وبعضهم فرق بين من ولد ... أعمى ومن عماه من بعد وجد"],[]],["فصل في اختلاف المتبايعين",["وحيثما اختلف بائع ومن ... منه اشترى إن كان في قدر الثمن","ولم يفت ما بيع فالفسخ إذا ... ما حلفا أو نكلا قد أنفذا","والبدء بالبائع ثم المشتري ... في الأخذ واليمين ذو تخير","ثم لكل واحد بعد الرضا ... وقيل إن تحالفا الفسخ مضى","وقيل لا يحتاج في الفسخ إلى ... حكم وسحنون له قد نقلا","وإن يفت فالقول للذي اشترى ... وذا الذي به القضاء قد جرى","وإن يكن في جنسه الخلف بدا ... تفاسخا بعد اليمين أبدا","وما يفوت واقتضى الرجوعا ... بقيمة فذاك يوم بيعا","وحيثما المبيع باق واختلف ... في أجل تفاسخا بعد الحلف","وقيل ذا إن ادعى المبتاع ما ... يبعد والعرف به قد عدما","وإن يفت فالقول عند مالك ... لبائع نهج اليمين سالك","وقيل للمبتاع والقولان ... لحافظ المذهب منقولان","وفي انقضاء أجل بذا قضي ... حتى يقول إنه لم ينقض","والقول قول مشتر بعد الحلف ... في القبض فيما بيعه نقدا عرف","وهو كذا لبائع فيما عدا ... مستصحب النقد ولو بعد مدا","كالدور والرقيق والرباع ... ما لم يجاوز حد الابتياع","والقبض للسلعة فيه اختلفا ... جار كقبض حكمه قد سلفا","القول قول مدع للأصل ... أو صحة في كل فعل فعل","ما لم يكن في ذاك عرف جار ... على خلاف ذاك ذو استقرار","وتابع المبيع كالسرج اختلف ... فيه يرد بيعه بعد الحلف","وذاك إن لم يفت المبيع ... ويبدأ اليمين من يبيع","وذا الذي قال به ابن القاسم ... وإن يفت فلاجتهاد الحاكم","وبيع من رشد كالدار ادعى ... بأنه في سفه قد وقعا","للمشتري القول به مع قسم ... وعكس هذا لابن سحنون نمي","ومن يكن بمال غيره اشترى ... والمشترى له للأمر أنكرا","وحلف الآمر فالمأمور ... منه ارتجاع ماله مأثور","وما له شيء على من باعا ... ما لم يكن قد صدق المبتاعا","وقيل بل يكون ذا تخير ... في أخذه من بائع أو مشتر","والبيع في القولين لن ينتقضا ... والمشتري له المبيع مقتضى"],[]],["فصل في حكم البيع على الغائب",["لطالب الحكم على الغياب ... ينظر في بعد وفي اقتراب","فمن على ثلاثة الأيام ... ونحوها يدعى إلى الأحكام","ويعذر الحاكم في وصوله ... بنفسه للحكم أو وكيله","فإن تمادى والمغيب حاله ... بيع بإطلاق عليه ماله","بعد ثبوت الموجبات الأول ... كالدين والغيبة والتمول","وما من الدين عليه قضيا ... وكالطلاق والعتاق أمضيا","وما له لحجة إرجاء ... في شأن ما جرى به القضاء","إلا مع اعتقاله من عذر ... مثل العدو وارتجاج البحر","والحكم مثل الحالة المقرره ... فيمن على مسافة كالعشره","وفي سوى استحقاق أصل أعملا ... والخلف في التفليس مع علم الملا","وذا له الحجة ترجى والذي ... بيع عليه ما له من منقذ","ويقتضي من موجب الرجوع ... من الغريم ثمن المبيع","وغائب من مثل قطر المغرب ... لمثل مكة ومثل يثرب","ما الحكم في شيء عليه يمتنع ... وهو على حجته ما تنقطع","والحكم ماض أبدا لا ينقض ... وما به أفيت لا ينتقض","لكن مع براءة يقضى له ... بأخذه من الغريم ما له"],[]],["فصل في العيوب",["وما من الأصول بيع وظهر ... للمشتري عيب به كان استتر","فإن يكن ليس له تأثير ... في ثمن فخطبه يسير","وما لمن صار له المبيع ... رد ولا بقيمة رجوع","وإن يكن ينقص بعض الثمن ... كالعيب عن صدع جدار بين","فالمشتري له الرجوع هاهنا ... بقيمة العيب الذي تعينا","وإن يكن لنقص ثلثه اقتضى ... فما علا فالرد حتم بالقضا","وكل عيب ينقص الأثمانا ... في غيرها رد به ما كانا","وبعضهم بالأصل عرضا ألحقا ... في أخذ قيمة على ما سبقا","ثم العيوب كلها لا تعتبر ... إلا بقول من له بها بصر","والمشتري الشيء وبعد يطلع ... فيه على عيب قيامه منع","إلا مع الفور ومهما استعملا ... بعد اطلاعه المعيب بطلا","كاللبس والركوب والبناء ... والهدم والجماع للإماء","وكامن يبدو مع التغيير ... كالسوس لا يرد في المأثور","والبق عيب من عيوب الدور ... ويوجب الرد على المشهور","وأجرة السمسار تسترد ... حيث يكون للمبيع رد","وحيثما عين قاض شهدا ... للعيب فالإعذار فيهم عهدا"],[]],["فصل في الغبن",["ومن بغبن في مبيع قاما ... فشرطه أن لا يجوز العاما","وأن يكون جاهلا بما صنع ... والغبن بالثلث فما زاد وقع","وعند ذا يفسخ بالأحكام ... وليس للعارف من قيام"],[]],["فصل في الشفعة",["وفي الأصول شفعة مما شرع ... في ذي الشياع وبحد تمتنع","ومثل بئر وكفحل النحل ... تدخل فيها تبعا للأصل","والماء تابع لها فيه احكم ... ووحده إن أرضه لم تقسم","والفرن والحمام والرحى القضا ... بالأخذ بالشفعة فيها قد مضى","وفي الثمار شفعة إن تنقسم ... وذا إن المشهور في ذاك التزم","ومثله مشترك من الثمر ... لليبس إن بدو الصلاح قد ظهر","ولم تبح للجار عند الأكثر ... وفي طريق منعت وأندر","والحيوان كله والبير ... وجملة العروض في المشهور","وفي الزروع والبقول والخضر ... وفي مغيب في الارض كالجزر","ونخلة حيث تكون واحده ... وشبهها وفي البيوع الفاسده","ما لم تصحح فبقيمة تجب ... كذاك ذو التعويض ذا فيه يجب","والخلف في صنف المقاثي اشتهر ... والأخذ بالشفعة فيه معتبر","والترك للقيام فوق العام ... يسقط حقه مع المقام","وغائب باق عليها وكذا ... ذو العذر لم يجد إليها منفذا","والأب والوصي مهما غفلا ... عن حدها فحكمها قد بطلا","وإن ينازع مشتر في الانقضا ... فللشفيع مع يمينه القضا","وليس الإسقاط بلازم لمن ... أسقط قبل البيع لا علم الثمن","كذلك ليس لازما من أخبرا ... بثمن أعلى وبالنقص الشرا","وشفعة في الشقص يعطى عن عوض ... والمنع في التبرعات مفترض","والخلف في أكرية الرباع ... والدور والحكم بالامتناع","وليس للشفيع من تأخير ... في الأخذ أو في الترك في المشهور","ولا يصح بيع شفعة ولا ... هبتها وإرثها لن يحظلا","وحيثما في ثمن الشقص اختلف ... فالقول قول مشتر مع الحلف","إن كان ما ادعاه ليس يبعد ... وقيل مطلقا ولا يعتمد","وابن حبيب قال بل يقوم ... وباختيار للشفيع يحكم","ومن له الشفعة مهما يدعي ... بيعا لشقص حيز بالتبرع","فما ادعاه فعليه البينه ... وخصمه يمينه معينه","والشقص لاثنين فأعلى مشترى ... يمنع أن يأخذ منه ما يرى","إن كان ما اشترى صفقة وما ... في صفقات ما يشاء التزما","والشركاء للشفيع وجبا ... أن يشفعوا معه بقدر الأنصبا","وما بعيب حط بالإطلاق ... عن الشفيع حط باتفاق","ولا يحيل مشتر لبائع ... على الشفيع لاقتضاء مانع","وليس للبائع أن يضمن عن ... مستشفع لمشتر من الثمن","ويلزم الشفيع حال ما اشتري ... من جنس أو حلول أو تأخر","وحيثما الشفيع ليس بالملي ... قيل له سق ضامنا أو عجل","وما ينوب المشتري فيما اشترى ... يدفعه له الشفيع محضرا"],[]],["فصل في القسمة",["ثلاث القسمة في الأصول ... وغيرها تجوز مع تفصيل","فقسمة القرعة بالتقويم ... تسوغ في تماثل المقسوم","ومن أبى القسم بها فيجبر ... وجمع حظين بها مستنكر","كذاك في اختلاف الأجناس وفي ... مكيل أو موزون المنع اقتفي","ولا يزيد بعضهم شيئا ولا ... يزاد في حظ لكي يعدلا","وبين أهل الحجر ليس يمتنع ... قسم بها ومدعي الغبن سمع","وهذه القسمة حيث تستحق ... يظهر فيها أنها تمييز حق","وقسمة الوفاق والتسليم ... لكن مع التعديل والتقويم","جمع لحظين بها لا يتقى ... وتشمل المقسوم كلا مطلقا","في غير ما من الطعام الممتنع ... فيه تفاضل ففيه تمتنع","وأعملت حتى على المحجور ... حيث بدا السداد في المشهور","وما مزيد العين بالمحظور ... ولا سواه هبه بالتأخير","ومن أبى القسم بها لا يجبر ... وقائم بالغبن فيها يعذر","وقسمة الرضا والاتفاق ... من غير تعديل على الإطلاق","كقسمة التعديل والتراضي ... فيما عدا الغبن من الأغراض","ومدع غبنا بها أو غلطا ... مكلف إن رام نقضا شططا","وقسمة الوصي مطلقا على ... محجوره مع غيره لن تحظل","فإن يكن مشاركا لمن حجر ... في قسمة فمنعه منها اشتهر","إلا إذا أخرجه مشاعا ... مع حظه قصدا فلا امتناعا","ويقسم القاضي على المحجور مع ... وصيه عند اقتفاء من منع","كذا له القسم على الصغار ... وغائب منقطع الأخبار","وحيث كان القسم للقضاة ... فبعد إثبات لموجبات","ويترك القسم على الأصاغر ... لحال رشد أو لوجه ظاهر","ومن دعا لبيع ما لا ينقسم ... لم يسمع إلا حيث إضرار حتم","مثل اشتراك حائط أو دار ... لا كالرحى والفرن في المختار","وكل ما قسمته تعذر ... تمنع كالتي بها تضرر","ويحكم القاضي بتسويق ومن ... يريد أخذه يزيد في الثمن","وإن أبوا قومه أهل البصر ... وآخذ له يقضي من يذر","وإن أبوا بيع عليهم بالقضا ... واقتسموا الثمن كرها أو رضا","والرد للقسمة حيث يستحق ... من حصة غير يسير مستحق","والغبن من يقوم فيه بعد ... أن طال واستقل قد تعدى","والمدعي لقسمة البنات ... يؤمر في الأصح بالإثبات","ولا يجوز قسم زرع أو ثمر ... مع الأصول والتناهي ينتظر","وحيثما الإبار فيهما عدم ... فالمنع من قسمة الأصل منحتم","ومع مأبور يصح القسم في ... أصوله لا فيه معها فاعرف","وقسم غير الثمر خرصا والعنب ... مما على الأشجار منعه وجب","وينقض القسم لوارث ظهر ... أو دين أو وصية فيما اشتهر","إلا إذا ما الوارثون باؤوا ... بحمل دين فلهم ما شاؤوا","والحلي لا يقسم بين أهله ... إلا بوزن أو بأخذ كله","وأجر من يقسم أو يعدل ... على الرؤوس وعليه العمل","كذلك الكاتب للوثيقه ... للقاسمين مقتف طريقه","وأجرة الكيال في التكسير ... من بائع تؤخذ في المشهور","كذاك في الموزون والمكيل ... الحكم ذا من غير ما تفصيل"],[]],["فصل في المعاوضة",["يجوز عقد البيع بالتعويض ... في جملة الأصول والعروض","ما لم يكن في الأصل زرع أو ثمر ... لم يؤبرا فما انعقاده يقر","وصح بالمأبور حيث يشترط ... من جهة فقط أو بقيا معا فقط","وسائغ للمتعاوضين ... من جهة فقط مزيد العين","لأجل ما كان من التفضيل ... بالنقد والحلول والتأجيل","وجائز في الحيوان كله ... تعاوض وإن يكن بمثله"],[]],["فصل في الإقالة",["إقالة تجوز فيما حلا ... بالمثل أو أكثر أو أقلا","وللمقال صحة الرجوع ... بحادث يحدث في المبيع","وفي القديم منه لا محاله ... بزائد إن كان في الإقاله","بعد اليمين أنه لم يكن ... يعلمه فيما مضى من زمن","والفسخ في إقالة مما انتهج ... بالصنعة التغيير كالغزل انتسج","إلا إذا المقال بالرضا دفع ... لمن أقال أجرة لما صنع","ولا يقال حيث لم يأت الأجل ... بثمن أدنى ولا وقت أقل","أو ثمن أكثر منه لأمد ... أبعد مما كان فيه المعتمد","وهي إذا كانت بمثل المال ... جائزة في كل حال حال","ومشتر أقال مهما اشترطا ... أخذ المبيع إن يبع تغبطا","بالثمن الأول فهو جائز ... والمشتري به المبيع حائز","وسوغت إقالة فيما اكتري ... إن لم يكن أعطى الكراء المكتري"],[]],["فصل في التولية والتصيير",["تولية المبيع جازت مطلقا ... وليس في الطعام ذاك متقى","والشرط في التصيير أن يقدرا ... دين والانجاز لما تصيرا","والعرض صيره بلا منازعه ... والحيوان حيث لا مواضعه","وجائز فيه مزيد العين ... حيث يقل عنه قدر الدين","والخلف في تصيير ما كالسكنى ... أو ثمر معين ليجنى","وامتنع التصيير للصبي ... إن لم يكن ذا أب أو وصي","والأب كالوصي في التصيير ... تمخيا بالجهل للمحجور"],[]],["فصل في السلم",["فيما عدا الأصول جوز السلم ... وليس في المال ولكن في الذمم","والشرح للذمة وصف قاما ... يقبل الالتزام والإلزاما","وشرط ما يسلم فيه أن يرى ... متصفا مؤجلا مقدرا","من كيل أو وزن وذرع أو عدد ... مما يصاب غالبا عند الأمد","وشرط رأس المال أن لا يحظلا ... في ذاك دفعه وأن يعجلا","وجاز إن أخر كاليومين ... والعرض فيه بخلاف العين"],[]],["باب الكراء وما يتصل به",["يجوز في الدور وشبهها الكرا ... لمدة حدت وشيء قدرا","ولا خروج عنه إلا بالرضا ... حتى يرى أمده قد انقضى","وجائز أن يكترى بقدر ... معين في العام أو في الشهر","ومن أراد أن يحل ما انعقد ... كان له ما لم يحد بعدد","وحيثما حل الكرا يدفع من ... قد اكترى منه بقدر ما سكن","كذاك إن بعض الكراء قدما ... فقدره من الكراء لزما","وشرط ما في الدور من نوع الثمر ... إذا بدا الصلاح فيه معتبر","وغير بادي الطيب إن قل اشترط ... حيث يطيب قبل ماله ارتبط","وما كنحل أو حمام مطلقا ... دخوله في الاكتراء متقى","وجاز شرط النقد في الأرحاء ... بحيث لا يخشى انقطاع الماء","وبالدقيق والطعام تكترى ... والبد بالزيت وينقد الكرا"],[]],["فصل في كراء الأرض وفي الجائحة فيه",["والأرض لا تكرى بجزء تخرجه ... والفسخ مع كراء مثل مخرجه","ولا بما تنبته غير الخشب ... من غير مزروع بها أو القصب","ولا بما كان من المطعوم ... كالشهد واللبن واللحوم","وتكترى الأرض لمدة تحد ... من سنة والعشر منتهى الأمد","وإن تكن شجرة بموضع ... جاز اكتراؤها بحكم التبع","ومكتر أرضا وبعد أن حصد ... أصاب زرعه انتشار بالبرد","فنابت بعد من المنتثر ... هو لرب الأرض لا للمكتري","وجائز كراء الأرض بالسنه ... والشهر في زراعة معينه","ومتوالي القحط والأمطار ... جائحة الكراء مثل الفار","ويسقط الكراء إما جمله ... أو بحساب ما الفساد حله","وليس يسقط الكرا في موجد ... بمثل صر أو بمثل برد"],[]],["فصل في أحكام من الكراء",["والعرض إن عرف عينا فالكرا ... يجوز فيه كالسروج والفرا","ومكتر لذاك لا يضمن ما ... يتلف عنده سوى إن ظلما","وهو مصدق مع اليمين ... وإن يكن من ليس بالمأمون","والمكتري إن مات لم يحن كرا ... واستؤنف الكراء كيف قدرا","حيث أبى الوارث إتمام الأمد ... واستوجبوا أخذ المزيد في العدد","والنقص بين العددين إن وجد ... له وفاء من تراث من فقد","وفي امرئ ممتع بالمال ... يموت قبل وقت الإستغلال","وقامت الزوجة تطلب الكرا ... قولان والفرق لمن تأخرا","وحالة المنع هي المستوضحه ... وشيخنا أبو سعيد رجحه","وشيخه محمد بن بكر ... إلى الوفاة مال عند النظر","فإن تكن والإزدراع قد مضى ... إبانه فلا كراء يقتضى","وإن تكن ووقت الإزدراع ... باق فما الكراء ذو امتناع","وفي الطلاق زرعه للزارع ... ثم الكراء ما له من مانع","وخيرت في الحرث في إعطاء ... قيمته والأخذ للكراء","وحيثما الزوجة ماتت فالكرا ... على الأصح لازم من عمرا","بقدر ما بقي للحصاد ... من بعد رعي حظه المعتاد","وإن تقع وقد تناهى الفرقه ... فالزوج دون شيء استحقه","ونزل الوارث في التأنيث ... وعكسه منزلة الموروث"],[]],["فصل في اختلاف المكري والمكتري",["القول للمكري مع الحلف اعتمد ... في مدة الكراء حيث ينتقد","ومع سكنى المكتر وما نقد ... تحالفا والفسخ في باقي الأمد","ثم يؤدي ما عليه حلفا ... في أمد السكنى الذي قد سلفا","وإن يكونا قبل سكنى اختلفا ... فالفسخ مهما نكلا أو حلفا","والقول في ذلك قول الحالف ... في لاحق الزمان أو في السالف","وإن يكن في القدر قبل السكنى ... تحالفا والفسخ بعد سنا","وإن يكن من بعد سكنى أقسما ... وفسخ باقي مدة قد لزما","وحصة السكنى يؤدي المكتري ... إن كان لم ينقد لماضي الأشهر","والقول من بعد انقضاء الأمد ... للمكتري والحلف إن لم ينقد","كذاك حكمه مع ادعائه ... لقدر باقي مدة اكترائه","والقول في القبض وفي الجنس لمن ... شاهده مع حلفه حال الزمن"],[]],["فصل في كراء الرواحل والسفن",["وفي الرواحل الكراء والسفن ... على الضمان أو بتعيين حسن","ويمنع التأجيل في المضمون ... ومطلقا جاز بذي التعيين","وحيث مكتر لعذر يرجع ... فلازم له الكراء أجمع","وواجب تعيين وقت السفر ... في السفن والمقر للذي اكتري","وهو على البلاغ إن شيء جرى ... فيها فلا شيء له من الكرا"],[]],["فصل في الإجارة",["العمل المعلوم من تعيينه ... يجوز فيه الأجر مع تبيينه","وللأجير أجرة مكمله ... إن تم أو بقدر ما قد عمله","والقول للعامل حيث يختلف ... في شأنها بعد الفراغ إن حلف","وإن جرى النزاع قبل العمل ... تحالفا والرد بين جلي","وإن يكن في صفة المصنوع ... أو نوعه النزاع ذا وقوع","فالقول للصانع من بعد الحلف ... وذاك في مقدار أجرة عرف","وإن يكن منه نكول حلفا ... رب المتاع وله ما وصفا","والقول قول صاحب المتاع في ... تنازع في الرد مع حلف قفي","والقول للأجير إن كان سأل ... بالقرب من فراغه أجر العمل","بعد يمينه لمن يناكر ... وبعد طول يحلف المستأجر","والوصف من مستهلك لما تلف ... في يده يقتضى به بعد الحلف","وشرطه إتيانه بمشبه ... وإن بجهل أو نكول ينتهي","فالقول قول خصمه في وصفه ... مستهلكا بمشبه مع حلفه","وكل من ضمن شيئا أتلفه ... فهو مطالب به أن يخلفه","وفي ذوات المثل مثل يجب ... وقيمة في غيره تستوجب"],[]],["فصل في الجعل",["الجعل عقد جائز لا يلزم ... لكن به بعد الشروع يحكم","وليس يستحق مما يجعل ... شيئا سوى إذا يتم العمل","كالحفر للبئر ورد الآبق ... ولا يحد بزمان لائق"],[]],["فصل في المساقاة",["إن المساقاة على المختار ... لازمة بالعقد في الأشجار","والزرع لم ييبس وقد تحققا ... قيل مع العجز وقيل مطلقا","وألحقوا المقاثي بالزرع وما ... كالورد والقطن على ما قدما","وامتنعت في مخلف الإطعام ... كشجر الموز على الدوام","وما يحل بيعه من الثمر ... وغير ما يطعم من أجل الصغر","وفي مغيب في الأرض كالجزر ... وقصب السكر خلف معتبر","وإن بياض قل ما بين الشجر ... وربه يلغيه فهو معتفر","وجاز أن يعمل ذاك العامل ... لكن بجزء جزآها يماثل","بشرط أن يكون ما يزدرع ... من عنده وجزء الأرض تبع","وحيثما اشترط رب الأرض ... فائده فالفسخ أمر مقضي","ولا تصح مع كراء لا ولا ... شرط البياض لسوى من عملا","ولا اشتراط عمل كثير ... يبقى له كمثل حفر بير","ولا اختصاصه بكيل أو عدد ... أو نخلة مما عليه قد عقد","وهي بشطر أو بما قد اتفق ... به وحد أمد لها يحق","والدفع للزكاة إن لم يشترط ... بينهما بنسبة الجزء فقط","وعاجز من حظه يكمل ... بالبيع مع بدو الصلاح العمل","وحيث لم يبد ولا يوجد من ... ينوب في ذاك مناب مؤتمن","فعامل يلغى له ما أنفقا ... وقول خذ ما ناب واخرج متقى"],[]],["فصل في الاغتراس",["والاغتراس جائز لمن فعل ... ممن له البقعة أو له العمل","والحد في خدمته أن يطعما ... ويقع القسم بجزء علما","وليس للعامل مما عملا ... شيء إلى ما جعلاه أجلا","وشرط بقيا غير موضع الشجر ... لرب الأرض سائغ إذا صدر","وشرط ما يثقل كالجدار ... ممتنع والعكس أمر جار","وجاز أن يعطى بكل شجره ... تنبت منه حصة مقدره"],[]],["فصل في المزارعة",["إن عمل العامل في المزارعه ... والأرض من ثان فلا ممانعه","إن أخرجا البذر على نسبة ما ... قد جعلاه جزء بينهما","كالنصف أو كنصفه أو السدس ... والعمل اليوم به في الأندلس","والتزمت بالعقد كالإجاره ... وقيل بل بالبدء للعماره","والدرس والنقلة مهما اشترطا ... مع عمل كان على ما شرطا","والشرط أن يخرج عن معمور ... مثل الذي ألفى من المحظور","وليس للشركة معه من بقا ... وبيعه منه يسوغ مطلقا","وحيث لا بيع وعامل زرع ... فغرمه القيمة فيه ما امتنع","وحق رب الأرض فيما قد عمر ... باق إذا لم ينبت الذي بذر","بعكس ما كان له نبات ... ولم يكن بعد له ثبات","وجاز في البذر اشتراك والبقر ... إن كان من ناحية ما يعتمر","والزرع للزرع في أشياء ... ورب الأرض يأخذ الكراء","كمثل ما في الغصب والطلاق ... وموت زوجين والاستحقاق","والخلف فيه هاهنا إن وقعا ... ما الشرع مقتض له أن يمنعا","قيل لذي البذر أو الحراثه ... أو محرز لاثنين من ثلاثه","الأرض والبذر والاعتمار ... وفيه أيضا غير ذاك جار","وقول مدع لعقد الإكترا ... لا الإزدراع مع يمين أثرا","وحيث زارع ورب الأرض قد ... تداعيا في وصف حرث يعتمد","فالقول للعامل واليمين ... وقلبها إن شاء مستبين"],[]],["فصل في الشركة",["شركة في مال أو في عمل ... أو فيهما تجوز لا لأجل","وفسخها إن وقعت على الذمم ... ويقسمان الربح حكم ملتزم","وإن يكن في العين ذاك اعتمدا ... تجز إن الجنس هناك اتحدا","وبالطعام جاز حيث اتفقا ... وهو لمالك بذاك متقى","وجاز بالعرض إذا ما قوما ... من جهة أو جهتين فاعلما","كذا طعام جهة لا يمتنع ... وعين أو عرض لدى الأخرى وضع","والمال خلطه ووضعه بيد ... واحد أو في الاشتراك معتمد","وحيثما يشتركان في العمل ... فشرطه اتحاد شغل ومحل","وحاضر يأخذ فائدا عرض ... في غيبة فوق الثلاث أو مرض","ومن له تحرف إن عمله ... في غير وقت تجره الفائد له"],[]],["فصل في القراض",["إعطاء مال من به يتاجر ... ليستفيد دافع وتاجر","مما يفاد فيه جزء يعلم ... هو القراض وبفعل يلزم","والنقد والحضور والتعيين ... من شرطه ويمنع التضمين","ولا يسوغ جعله إلى أجل ... وفسخه مستوجب إذا نزل","ولا يجوز شرط شيء ينفرد ... به من الربح وإن يقع يرد","والقول قول عامل إن يختلف ... في جزء القراض أو حال التلف","كذاك في ادعائه الخساره ... وكونه قراضا أو إجاره","وليس للعامل في غير السفر ... نفقة والترك شرط لا يقر","وعندما مات ولا أمين في ... وراثه ولا أتوا بالخلف","رد إلى صاحبه المال ولا ... شيء من الربح لمن قد عملا","وهو إذا أوصى به مصدق ... في صحة أو مرض يستوثق","وأجر مثل أو قراض مثل ... لعامل عند فساد الأصل"],[]],["باب التبرعات",["الحبس في الأصول جائز وفي ... منوع العين بقصد السلف","ولا يصح في الطعام واختلف ... في الحيوان والعروض من سلف","وللكبار والصغار يعقد ... وللجنين ولمن سيولد","ويجب النص على الثمار ... والزرع حيث الحبس للصغار","ومن يحبس دار سكناه فلا ... يصح إلا أن يعاين الخلا","ونافذ تحبيس ما قد سكنه ... بما كالاكتراء من بعد السنه","إن كان ما حبس للكبار ... ومثل ذاك في الهبات جاري","وكل ما يشترط المحبس ... من سائغ شرعا عليه الحبس","مثل التساوي ودخول الأسفل ... وبيع حظ من بفقر ابتلي","وحيث جاء مطلقا لفظ الولد ... فولد الذكور داخل فقد","لا ولد الإناث إلا حيثما ... بنت لصلب ذكرها تقدما","ومثله في ذا بني والعقب ... وشامل ذريتي فمنسحب","والحوز شرط صحة التحبيس ... قبل حدوث موت أو تفليس","لحائز القبض وفي المشهور ... إلى الوصي القبض للمحجور","ويكتفى بصحة الإشهاد ... إن أعوز الحوز لعذر باد","وينفذ التحبيس في جميع ما ... محبس لقبضه قد قدما","والأخ للصغير قبضه وجب ... مع اشتراك وبتقديم من أب","والأب لا يقبض للصغير مع ... كبيره والحبس إرث إن وقع","إلا إذا ما أمكن التلافي ... وصحح الحوز بوجه كاف","وإن يقدم غيره جاز وفي ... جزء معاش حكم تحبيس قفي","ونافذ ما حازه الصغير ... لنفسه وبالغ محجور","وبانسحاب نظر المحبس ... للموت لا يثبت حكم الحبس","ومن لسكنى دار تحبيس سبق ... تضيق عمن دونه بها أحق","ومن يبيع من عليه حبسا ... يرد مطلقا ومع علم أسا","والخلف في المبتاع هل يعطي الكرا ... واتفقوا مع علمه قبل الشرا","ويقتضي الثمن إن كان تلف ... من فائد المبيع حتى ينتصف","وإن يمت من قبل لا شيء له ... وليس يعدو حبس محله","وغير أصل عادم النفع صرف ... ثمنه في مثله ثم وقف","ولا تبت قسمة في حبس ... وطالب قسمة نفع لم يسي"],[]],["فصل في الصدقة والهبة وما يتعلق بهما",["صدقة تجوز إلا مع مرض ... موت وبالدين المحيط تعترض","ولا رجوع بعد للمصدق ... وملكها بغير إرث اتقي","كذاك ما وهب للأيتام ... والفقراء وأولي الأرحام","والأب حوزه لما تصدقا ... به على محجوره لن يتقى","وللمعينين بالحوز تصح ... وجبره مهما أباه متضح","وفي سوى المعينين يؤمر ... بالحوز والخلف أتى هل يجبر","والجبر محتوم بذي تعين ... لصنفهم من جهة المعين","وللأب التقديم للكبير ... لقبض ما يختص بالصغير","وحوز حاضر لغائب إذا ... كانا شريكين بها قد أنفذا","وما على البت لشخص عينا ... فهو له ومن تعدى ضمنا","وغير ما يبت إذ يعين ... رجوعه للملك ليس يحسن","وللأب القبض لما قد وهبا ... ولده الصغير شرعا وجبا","إلا الذي يهب من نقديه ... فشرطه الخروج من يديه","إلى أمين وعن الأمين ... يغني اشتراء هبه بعد حين","وإن يكن موضع سكناه يهب ... فإن الإخلاء له حكم وجب","ومن يصح قبضه وما قبض ... معطاه مطلقا لتفريط عرض","يبطل حقه بلا خلاف ... إن فاته في ذلك التلافي"],[]],["فصل في الاعتصار",["الإعتصار جاز فيما يهب ... أولاده قصد المحبة الأب","والأم ما حي أب تعتصر ... وحيث جاز الإعتصار يذكر","وضمن الوفاق في الحضور ... إن كان الإعتصار من كبير","وكل ما يجري بلفظ الصدقه ... فالإعتصار أبدا لن يلحقه","ولا اعتصار مع موت أو مرض ... له أو النكاح أو دين عرض","وفقر موهوب له ما كانا ... لمنع الاعتصار قد أبانا","وما اعتصار بيع شيء قد وهب ... من غير إشهاد به كما يجب","لكنه يعد مهما صيرا ... ذاك لموهوب له معتصرا","وقيل بل يصح إن مال شهر ... له وإلا فلحوز يفتقر"],[]],["فصل في العمرى وما يلحق بها",["هبة غلة الأصول العمرى ... بحوز الأصل حوزها استقرا","طول حياة معمر أو مده ... معلومة كالعام أو ما بعده","وبيعها مسوغ للمعمر ... من معمر أو وارث للمعمر","وغلة للحيوان إن تهب ... فمنحة تدعى وليست تجتنب","وخدمة العبد هي الإخدام ... والحوز فيهما له التزام","حياة مخدم أو الممنوح ... أو أمد عين بالتصريح","وأجرة الراعي لما قد منحا ... على الذي بمنحة قد سمحا","وجائز لمانح فيها الشرا ... بما يراه ناجزا أو مؤخرا"],[]],["فصل في الإرفاق",["إرفاق جار حسن للجار ... بمسقى أو طريق أو جدار","والحد في ذاك إن حد اقتفي ... وعد في إرفاقه كالسلف"],[]],["فصل في حكم الحوز",["والأجنبي إن يحز أصلا بحق ... عشر سنين فالتملك استحق","وانقطعت حجة مدعيه ... مع الحضور عن خصام فيه","إلا إذا أثبت حوزا بالكرا ... أو ما يضاهيه فلن يعتبرا","أو يدعي حصوله تبرعا ... من قائم فليثبتن ما ادعا","أو يحلف القائم واليمين له ... إن ادعى الشراء منه معمله","ويثبت الدفع وإلا الطالب ... له اليمين والتقضي لازب","وإن يكن مدعيا إقاله ... فمع يمينه له المقاله","والتسع كالعشر لدى ابن القاسم ... أو الثمان في انقطاع القائم","والمدعي إن أثبت النزاع مع ... خصيمه في مدة الحوز انتفع","وقائم ذو غيبة بعيده ... حجته باقية مفيده","والبعد كالسبع وكالثمان ... وفي التي توسطت قولان","وكالحضور اليوم واليومان ... بنسبة الرجال لا النسوان","والأقربون حوزهم مختلف ... بحسب اعتمارهم يختلف","فإن يكن بمثل سكنى الدار ... والزرع للأرض والاعتمار","فهو بما يجوز الأربعين ... وذو تشاجر كالأبعدين","ومثله ما حيز بالعتاق ... ما كان أو بالبيع باتفاق","وفيه بالهدم وبالبنيان ... والغرس أو عقد الكرا قولان","وفي سوى الأصول حوز الناس ... بالعام والعامين في اللباس","وما كمركوب ففيه لزما ... حوز بعامين فما فوقهما","وفي العبيد بثلاثة فما ... زاد حصول الحوز فيما استخدما","والوطء للإماء باتفاق ... مع علمه حوز على الإطلاق","والماء للأعلين فيما قدما ... والأسفل الأقدم فيه قدما","وما رمى البحر به من عنبر ... ولؤلؤ واجده به حري"],[]],["فصل في الإستحقاق",["المدعي استحقاق شيء يلزم ... بينة مثبتة ما يزعم","من غير تكليف لمن تملكه ... من قبل ذا بأي وجه ملكه","ولا يمين في أصول ما استحق ... وفي سواها قبل الاعذار يحق","وحيثما يقول ما لي مدفع ... فهو على من باع منه يرجع","وإن يكن له مقال أجلا ... فإن أتى بما يفيد أعملا","وما له في عجزه رجوع ... على الذي كان له المبيع","والأصل لا توقيف فيه إلا ... مع شبهة قوية تجلى","وفي سوى الأصل بدعوى المدعي ... بينة حاضرة في الموضع","وما له عين عليها يشهد ... من حيوان أو عروض توجد","ويكتفى في حوز الأصل المستحق ... بواحد عدل والإثنان أحق","وناب عن حيازة الشهود ... توافق الخصمين في الحدود","وواجب إعمالها إن الحكم ... بقسمة على المحاجير حكم","وجاز أن يثبت ملكا شهدا ... وبالحيازة سواهم شهدا","إن كان ذا تسمية معروفة ... ونسبة مشهورة مألوفة","ومشتري المثلي مهما يستحق ... معظم ما اشتري فالتخيير حق","في الأخذ للباقي من المبيع ... بقسطه والرد للجميع","وإن يكن منه اليسير ما استحق ... يلزمه الباقي بما له يحق","وما له التقويم باستحقاق ... أنفسه يرد بالإطلاق","إن كان في معين ولا يحل ... إمساك باقيه لما فيه جهل","وإن يكن أقله فالحكم أن ... يرجع في حصته من الثمن","وإن يكن على الشياع المستحق ... وقبل القسمة فالقسم استحق","والخلف في تمسك بما بقي ... بقسطه مما انقسامه اتقي","وإن يكن في الفيء مال المسلم ... فهو له من قبل قسم المغنم","وإن يقم من بعد ما قد قسما ... فهو به أولى بما تقوما","ومشتر وحائز ما ساق من ... أمن لا يؤخذ منه بالثمن","ويؤخذ المأخوذ من لص بلا ... شيء وما يفدى بما قد بذلا"],[]],["فصل في العارية والوديعة والأمناء",["وما استعير رده مستوجب ... وما ضمان المستعير يجب","إلا بقابل المغيب لم تقم ... بينة عليه أنه عدم","أو ما المعار فيه قد تحققا ... تعد أو فرط فيه مطلقا","والقول قول مستعير حلفا ... في رد ما استعار حيث اختلفا","ما لم يكن مما يغاب عاده ... عليه أو أخذ بالشهاده","فالقول للمعير فيما بينه ... ومدعي الرد عليه البينه","والقول في المدة للمعير ... مع حلفه وعجز مستعير","كذاك في مسافة لما ركب ... قبل الركوب ذا له فيه يجب","والمدعي مخير أن يركبا ... مقدار ما حد له أو يذهبا","والقول من بعد الركوب ثبتا ... للمستعير إن بمشبه أتى","وإن أتى فيه بما لا يشبه ... فالقول للمعير لا يشتبه","والقول قول مدعي الكراء في ... ما يستعار مع يمين اقتفي","ما لم يكن ذلك لا يليق ... به فقلب القسم التحقيق","ويضمن المودع مع ظهور ... مخايل التضييع والتقصير","ولا ضمان فيه للسفيه ... ولا الصغير مع ضياع فيه","والتجر بالمودع من أعمله ... يضمنه والربح كله له","والقول قول مودع فيما تلف ... وفي ادعاء ردها مع الحلف","ما لم يكن يقبضه ببينه ... فلا غنا في الرد أن يبينه","والأمناء في الذي يلونا ... ليسوا لشيء منه يضمنونا","كالأب والوصي والدلال ... ومرسل صحبته بالمال","وعامل القراض والموكل ... وصانع لم ينتصب للعمل","وذو انتصاب مثله في عمله ... بحضرة الطالب أو بمنزله","والمستعير مثلهم والمرتهن ... في غير قابل المغيب فاستبن","ومودع لديه والأجير ... فيما عليه الأجر والمأمور","ومثله الراعي كذا ذو الشركه ... في حالة البضاعة المشتركه","وحامل للثقل بالإطلاق ... وضمن الطعام باتفاق","والقول قولهم بلا يمين ... والإتهام غير مستبين","وقيل من بعد اليمين مطلقا ... والأول الأولى لدى من حققا","وحارس الحمام ليس يضمن ... وبعضهم يقول بل يضمن"],[]],["فصل في القرض وهو السلف",["القرض جائز وفعل جار ... في كل شيء ما عدا الجواري","وشرطه أن لا يجر منفعه ... وحاكم بذاك كل منعه","وليس باللازم أن يردا ... قبل انقضاء أجل قد حدا","وإن رأى مسلف تعجيله ... ألزم من سلفه قبوله"],[]],["باب في العتق وما يتصل به",["العتق بالتدبير والوصاة ... وبالكتابة وبالبتات","وليس في التدبير والتبتيل ... إلى الرجوع بعد من سبيل","والعتق بالمال هو المكاتبه ... وما له بالجبر من مطالبه","ومعتق للجزء من عبد له ... مطالب بالحكم أن يكمله","وحظ من شاركه يقوم ... عليه في اليسر وعتقا يلزم","وعتق من سيده يمثل ... به إذا ما شأنه يبتل","ومن بمال عنقه منجم ... يكون عبدا مع بقاء درهم","والقول للسيد في مال حصل ... والخلف في قدر وجنس وأجل","وحكمه كالحر في التصرف ... ومنع رهن وضمان اقتفي"],[]],["باب في الرشد والأوصياء والحجر والوصية والإقرار والدين والفلس",["الرشد حفظ المال مع حسن النظر ... وبعضهم له الصلاح معتبر","والإبن ما دام صغيرا للأب ... إلى بلوغ حجره فيما اجتبي","إن ظهر الرشد ولا قول لأب ... وبالغ بالعكس حجره وجب","كذاك من أبوه حجرا جددا ... عليه في فور البلوغ مشهدا","وبالغ وحاله قد جهلا ... على الرشاد حمله وقيل لا","وإن يمت أب وقد وصى على ... مستوجب حجرا مضى ما فعلا","ويكتفي الوصي بالإشهاد ... إذا رأى مخايل الرشاد","وفي ارتفاع الحجر مطلقا يجب ... إثبات موجب لترشيد طلب","ويسقط الإعذار في الترشيد ... حيث وصيه من الشهود","والبالغ الموصوف بالإهمال ... معتبر بوصفه في الحال","فظاهر الرشد يجوز فعله ... وفعل ذي السفه رد كله","وذاك مروي عن ابن القاسم ... من غير تفصيل له ملائم","ومالك يجيز كل ما صدر ... بعد البلوغ عنه من غير نظر","وعن مطرف أتى من اتصل ... سفهه فلا يجوز ما فعل","وإن يكن سفه بعد الرشد ... ففعله ليس له من رد","ما لم يبع من خادع فيمنع ... وبالذي أفاته لا يتبع","ومعلن السفه رد ابن الفرج ... أفعاله والعكس في العكس اندرج","وفعل من يجهل بالإطلاق ... حالته يجوز باتفاق","ويجعل القاضي بكل حال ... على السفيه حاجرا في المال","وإن تكن بنت وحاضت والأب ... حي فليس الحجر عنها يذهب","إلا إذا ما نكحت ثم مضى ... سبعة أعوام وذا به القضا","ما لم يجدد حجرها إثر البنا ... أو سلم الرشد الذي تبينا","وحجر من وصى عليها ينسحب ... حتى يزول حكمه بما يجب","والعمل اليوم عليه ماض ... ومثله حجر وصي القاضي","وإن تكن ظاهرة الإهمال ... فإنها مردودة الأفعال","إلا مع الوصول للتعنيس ... أو مكث عام أثر التعريس","وقيل بل أفعالها تسوغ ... إن هي حالة المحيض تبلغ","والسن في التعنيس من خمسين ... فيما به الحكم إلى الستين","وحيث رشد الوصي من حجر ... ولاية النكاح تبقى بالنظر","وليس للمحجور من تخلص ... إلا بترشيد إذا مات الوصي","وبعضهم قد قال بالسراح ... في حق من يعرف بالصلاح","والشأن الاكثار من الشهود ... في عقدي التسفيه والترشيد","وليس يكفي فيهما العدلان ... وفي مرد الرشد يكفيان","وجاز للوصي فيمن حجرا ... إعطاء بعض ماله مختبرا","وكل ما أتلفه المحجور ... فغرمه من ماله المشهور","إلا إذا طوعا إليه صرفه ... وفي سوى مصلحة قد أتلفه","وفعله بعوض لا يرتضى ... وإن أجازه وصيه مضى","وفي التبرعات قد جرى العمل ... بمنعه ولا يجاز إن فعل","وظاهر السفه جاز الحلما ... من غير حجر فيه خلف علما","جواز فعله بأمر لازم ... لمالك والمنع لابن القاسم","وبالذي على صغير مهمل ... يقضى إذا صح بموجب جلي","وهو على حجته كالغائب ... إلى بلوغه بحكم واجب","ويدفع الوصي كل ما يجب ... من مال من في حجره مهما طلب","ونظر الوصي في المشهور ... منسحب على بني المحجور","ويعقد النكاح للإماء ... والنص في عقد البنات جاء","وعقده قبل البلوغ جار ... بجعله في البكر كالإجبار","والنقل للإيصاء غير معمل ... إلا لعذر أو حلول أجل","ولا يرد العقد بعد أن قبل ... إن مات موص ولعذر ينعزل","ولا رجوع إن أبى تقدمه ... من بعد أن مات الذي قد قدمه","وكل من قدم من قاض فلا ... يجوز أن يجعل منه بدلا","كذاك لا يجوز أن ينعزلا ... إلا لعذر بين إن قبلا","وصالح ليس يجيد النظرا ... في المال إن خيف الضياع حجرا","وشارب الخمر إذا ما ثمرا ... لما يلي من ماله لن يحجرا","وللوصي جائز أن يتجرا ... لكنه يضمن مهما غررا","وعندما يأنس رشد من حجر ... يطلقه وماله له يذر","وحيث لم يفعل فقد تصدى ... أن يضمن المال لأن تعدى"],[]],["فصل في الوصية وما يجري مجراها",["في ثلث المال فأدنى في المرض ... أو صحة وصية لا تعترض","حتى من السفيه والصغير ... إن عقل القربة في الأمور","العبد لا تصح منه مطلقا ... وهي من الكفار ليست تتقى","وهي لمن تملك منه يصح ... حتى لحمل واضح أو لم يضح","لكنها تبطل إن لم يستهل ... وللعبيد دون إذن تستقل","وليس من شيء لمن يوصى له ... إلا إذا الموصي يموت قبله","وهي بما يملك حتى الثمر ... والدين والحمل وإن لم يظهر","وامتنعت لوارث إلا متى ... إنقاذ باقي الوارثين ثبتا","وللذي أوصى ارتجاع ما يرى ... من غير ما بتل أو ما دبرا","وفي الذي علم موص تجعل ... ودين من عن اليمين ينكل","وصححت لولد الأولاد ... والأب للميراث بالمرصاد","وإن أب من ماله قد أنفقا ... على ابنه في حجره ترفقا","فجائز رجوعه في الحال ... عليه من حين اكتساب المال","وإن يمت والمال عين باقي ... وطالب الوارث بالإنفاق","فما لهم إليه من سبيل ... وهو للابن دون ما تعليل","إلا إذا أوصى على الحساب ... وقيد الإنفاق بالكتاب","وإن يكن عرضا وكان عنده ... فلهم الرجوع فيه بعده","إلا إذا ما قال لا تحاسبوا ... وترك الكتب فلن يطالبوا","وكالعروض الحيوان مطلقا ... فيه الرجوع بالذي قد أنفقا","وإن يكن عينا ورسما أصدرا ... بأنه ذمته قد عمرا","فما تحاسب لمستحق ... وهو كالحاضر دون فرق","وإن يكن في ماله قد أدخله ... من غير إشهاد بذاك أعمله","مع علم أصله فههنا يجب ... رجوع وارث بإنفاق طلب","وغير مقبوض على الإطلاق ... كالعرض في الرجوع باتفاق","وموت الإبن حكمه كموت الأب ... وقيل في يسر أب حلف وجب"],[]],["فصل في الإقرار",["ومالك لأمره أقر في ... صحته لأجنبي اقتفي","وما لوارث ففيه اختلفا ... ومنفذ له لتهمة نفى","ورأس متروك المقر ألزما ... وهو به في فلس كالغرما","وإن يكن لأجنبي في المرض ... غير صديق فهو نافذ الغرض","ولصديق أو قريب لا يرث ... يبطل ممن بكلالة ورث","وقيل بل يمضي بكل حال ... وعندما يؤخذ بالإبطال","قيل بإطلاق ولابن القاسم ... يمضي من الثلث بحكم جازم","وحيثما الإقرار فيه للولد ... مع غيره فليس فيه من مرد","مع ظهور سبب الإقرار ... فإن يكن ذاك عن اختيار","فذو عقوق وانحراف يحكم ... له به وذو البرور يحرم","وإن يكن لزوجة بها شغف ... فالمنع والعكس بعكس يتصف","وإن جهلنا عند ذاك حاله ... فالمنع ممن إرثه كلاله","ومع واحد من الذكور ... في كل حال ليس بالمحظور","كذاك مع تعدد فيهم ذكر ... ما منهم ذو صغر وذو كبر","وإن يكن بغير ذاك مطلقا ... قيل مسوغ وقيل متقى","وإن يكن لوارث غيرهما ... مع ولد ففي الأصح لزما","ودونه لمالك قولان ... بالمنع والجواز مرويان","وحالة الزوجة والزوج سوا ... والقبض للدين مع الدين استوا","ومشهد في موطنين بعدد ... لطالب ينكر أنه اتحد","لهم به قولان واليمين ... على كليهما له تعيين","ما لم يكن ذاك برسمين ثبت ... فما ادعاه مشهد لا يلتفت","ومن أقر مثلا بتسعه ... وصح أن دفع منها السبعه","ثم أتى من بعد ذا ببينه ... بقبض دينارين منه معلنه","فالقول قوله إن الخصم ادعى ... دخول دينارين فيما اندفعا","وبيع من حابى من المردود ... إن ثبت التوليج بالشهود","إما بالاقرار أو الاشهاد ... لهم به في وقت الانعقاد","ومع ثبوت ميل بائع لمن ... منه اشترى يحلف في دفع الثمن"],[]],["فصل في حكم المديان",["ومن عليه الدين إما موسر ... فمطله ظلم ولا يؤخر","أو معسر قضاؤه إضرار ... فينبغي في شأنه الإنظار","أو معدم وقد أبان معذره ... فواجب إنظاره لميسره","ومن على الأموال قد تقعدا ... فالضرب والسجن عليه سرمدا","ولا التفات عند ذا لبينه ... لما ادعى من عدم مبينه","وإن أتي بضامن فبالأدا ... حتى يؤدي ما عليه قعدا","وحيثما يجهل حال من طلب ... وقصد اختباره بما يجب","فحبسه مقدار نصف شهر ... إن يكن الدين يسير القدر","والسجن في توسط شهران ... وضعف ذين في الخطير الشان","وحيث جاء قبل بالحميل ... بالوجه ما للسجن من سبيل","وسلعة المديان رهنا تجعل ... وبيعها عليه لا يعجل","وحقه مع ذاك أن يؤخرا ... بحسب المال لما القاضي يرى","والحبس للملد والمتهم ... إلى الأداء أو ثبوت العدم","وليس ينجيه من اعتقال ... إلا حميل غارم للمال","وحبس من غاب على المال إلى ... أدائه أو موته معتقلا","وغير أهل الوفر مهما قصدا ... تأخيره وبالقضاء وعدا","مكن من ذاك بضامن وإن ... لم يأت بالضامن للمال سجن","ومن له وفر فليس يضمن ... فإن قضى الحق وإلا يسجن","وأوجب ابن زرب أن يحلفا ... من كان باكتساب عين عرفا","ومحمل الناس على حال الملا ... على الأصح وبه الحكم خلا","ويشهد الناس بضعف أو عدم ... ولا غنى في الحالتين من قسم","بما اقتضاه الرسم لا اليقين ... إذ لا يصح بت ذي اليمين","ومن نكوله عن الحلف بدا ... فإنه يسجن بعد أبدا","وحيث تم رسمه وعدما ... كان عديما لأولاء الغرما","إلا إذا استفاد من بعد العدم ... مالا فيطلبونه بالملتزم","وينبغي إعلان حال المعدم ... في كل مشهد بأمر الحاكم","ومثبت للضعف حال دفعه ... لغرمائه بقدر وسعه","وطالب تفتيش دار المعسر ... ممتنع إسعافه في الأكثر"],[]],["فصل في الفلس",["ومن بماله أحاط الدين لا ... يمضي له تبرع إن فعلا","وإن يكن للغرما في أمره ... تشاور فلا غنى عن حجره","وحل ما عليه من ديون ... إذ ذاك كالحلول بالمنون","والإعتصار ليس بالمكلف ... له ولا قبول غير السلف","وهو مصدق إذا ما عينا ... مالا له وما عليه أمنا","ورب الأرض المكتراة إن طرق ... تفليس أو موت بزرعها أحق","واحكم بذا بائع أو صانع ... فيما بأيديهم فما من مانع","وما حواه مشتر ويحضر ... فربه في فلس مخير","إلا إذا ما الغرماء دفعوا ... ثمنه فأخذه ممتنع","وليس من رد بعيب ما اشترى ... أولى به في فلس إن اعترى","والخلف في سلعة بيع فاسد ... ثالثها اختصاصها بالناقد","وزوجة في مهرها كالغرما ... في فلس لا في الممات فاعلما","وحارس المتاع والزرع وما ... أشبهه معهم قد قسما"],[]],["باب في الضرر وسائر الجنايات",["ومحدث ما فيه للجار ضرر ... محقق يمنع من غير نظر","كالفرن والباب ومثل الأندر ... أو ما له مضرة بالجدر","فإن يكن يضر بالمنافع ... كالفرن بالفرن فما من مانع","وهو على الحدوث حتى يثبتا ... خلافه بذا القضاء ثبتا","وإن يكن تكشفا فلا يقر ... بحيث الأشخاص تبين والصور","وما بنتن الريح يؤذي يمنع ... فاعله كالدبغ مهما يقع","وقول من يثبته مقدم ... على مقال من بنفي يحكم","وإن جدار ساتر تهدما ... أو كان خشية السقوط هدما","فمن أبى بناءه لن يجبرا ... وقيل للطالب إن شئت استرا","وعامد للهدم دون مقتض ... عليه بالبناء وحده قضي","إن كان ذا وجد وكان ماله ... والعجز عنه أدبا أناله","وإن يكن مشتركا فمن هدم ... دون ضرورة بناءه التزم","وإن يكن لمقتض فالحكم أن ... يبني مع شريكه وهو السنن","من غير إجبار فإن أبى قسم ... موضعه بينهما إذا حكم","وإن تداعياه فالقضاء ... لمن له العقود والبناء"],[]],["فصل في ضرر الأشجار",["وكل ما كان من الأشجار ... جنب جدار مبدي انتشار","فإن يكن بعد الجدار وجدا ... قطع ما يؤذي الجدار أبدا","وحيث كان قبله يشمر ... وتركه وإن أضر الأشهر","ومن تكن له بملك شجره ... أغصانها عالية منتشره","فلا كلام عند ذا لجارها ... لا في ارتفاعها ولا انتشارها","وكل ما خرج عن هواء ... صاحبها يقطع باستواء","وإن تكن بملك من ليست له ... وانتشرت حتى أطلت جله","فما لرب الملك قطع ما انتشر ... لعلمه بأن ذا شأن الشجر","والحكم في الطريق حكم الجار ... في قطع ما يؤذي من الأشجار"],[]],["فصل في مسقط القيام بالضرر",["وعشرة الأعوام لامرئ حضر ... تمنع إن قام بمحدث الضرر","وذا به الحكم وبالقيام ... قد قيل بالزائد في الأيام","ومن رأى بنيان ما فيه ضرر ... ولم يقم من حينه بما ظهر","حتى رأى الفراغ من إتمامه ... مكن باليمين من قيامه","فإن يبع بعد بلا نزاع ... فلا قيام فيه للمبتاع","وإن يكن حين الخصام باعا ... فالمشتري يخصم ما استطاعا","ومانع الشمس أوالريح معا ... لجاره بما بنى لن يمنعا"],[]],["فصل في الغصب والتعدي",["وغاصب يغرم ما استغله ... من كل شيء ويرد أصله","حيث يرى بحاله فإن تلف ... قوم والمثل بذي مثل ألف","والقول للغاصب في دعوى التلف ... وقدر مغصوب وما به اتصف","والغرم والضمان مع علم يجب ... على الذي انجر إليه ما غصب","بإرث أو من واهب أو بائع ... كالمتعدي غاصب المنافع","وشبهة كالملك في ذا الشأن ... لقوله الخراج بالضمان","ولا يكون الرد في استحقاق ... وفاسد البيع على الإطلاق","والرد بالعيب ولا في السلعه ... موجودة في فلس والشفعه","ومتلف منفعة مقصوده ... مما له كيفية معهوده","صاحبه خير في الأخذ له ... مع أخذه الأرش عيب حله","أو أخذه لقيمة المعيب ... يوم حدوث حالة التعييب","وليس إلا الأرش حيث المنفعه ... يسيرة والشيء معها في سعه","من بعد رفو الثوب أو إصلاح ... ما كان منه قابل الصلاح"],[]],["فصل في الاغتصاب",["وواطئ لحرة مغتصبا ... صداق مثلها عليه وجبا","إن ثبت الوطء ولو ببينه ... بأنه غاب عليها معلنه","وقيمة النقص عليه في الأمه ... هبها سوى بكر وغير مسلمه","والولد استرق حيث علما ... والحد مع ذاك عليه فيهما","وإن يكن ذا الغصب بالدعوى ففي ... تفصيله بيان حكمه يفي","فحيثما الدعوى على من قد شهر ... بالدين والصلاح والفضل نظر","فإن تكن بعد التراخي زمنا ... حدت لقذف وبحمل للزنا","وحيثما رحمها منه بري ... فالحد تستوجبه في الأظهر","وذاك في المجهول حالا إن جهل ... حال لها أو لم تحز صونا نقل","وإن تكن ممن لها صون ففي ... وجوبه تخريجا الخلف قفي","وحيث قيل لا تحد إن نكل ... فالمهر مع يمينها لها حصل","وما على المشهور بالعفاف ... مهر ولا حلف بلا خلاف","وحيث دعوى صاحبت تعلقا ... حد الزنا يسقط عنها مطلقا","والقذف فيه الحد لابن القاسم ... وحلفه لديه غير لازم","ومن نفى الحد فعنده يجب ... تحليفه بأن دعواها كذب","ومع نكوله لها اليمين ... وتأخذ الصداق ما يكون","وحدها له اتفاقا إن تكن ... ليس لها صون ولا حال حسن","وعدم الحد كذا للمنبهم ... حالا إذا كانت توقى ما يصم","وإن تكن لا تتوقى ذلك ... فالخلف تخريجا بدا هنالك","وفي ادعائها على المشتهر ... بالفسق حالتان للمعتبر","حال تشبث وبكر تدمى ... فذي سقوط الحد عنها عمى","في القذف والزنا وإن حمل ظهر ... وفي وجوب المهر خلف معتبر","وحيث قيل إنها تستوجبه ... فبعد حلف في الأصح تطلبه","وإن يكن مجهول حال فيجب ... تحليفه ومع نكول ينقلب","وحالة بعد زمان الفعل ... فالحد ساقط سوى مع حمل","ولا صداق ثم إن لم ينكشف ... من أمره بالسجن شيء فالحلف","وإن أبى من اليمين حلفت ... ولصداق المثل منه استوجبت"],[]],["فصل في دعوى السرقة",["ومدع على امرئ أن سرقه ... ولم تكن دعواه بالمحققه","فإن يكن مدعيا ذاك على ... من حاله في الناس حال الفضلا","فليس من كشف لحاله ولا ... يبلغ بالدعوى عليه أملا","وإن يكن مطالبا من يتهم ... فمالك بالضرب والسجن حكم","وحكموا بصحة الإقرار ... من ذاعر يحبس لاختبار","ويقطع السارق باعتراف ... أو شاهدي عدل بلا خلاف","ومن أقر ولشبهة رجع ... درئ عنه الحد في الذي وقع","ونقلوا في فقدها قولين ... والغرم واجب على الحالين","وكل ما سرق وهو باق ... فإنه يرد باتفاق","وحيثما السارق بالحكم قطع ... فبالذي سرق في اليسر اتبع","والحد لا الغرم على العبد متى ... أقر بالسرقة شرعا ثبتا"],[]],["فصل في أحكام الدماء",["القتل عمدا للقصاص موجب ... بعد ثبوته بما يستوجب","من اعتراف ذي بلوغ عاقل ... أو شاهدي عدل بقتل القاتل","أو بالقسامة وباللوث تجب ... وهو بعدل شاهد بما طلب","أو بكثير من لفيف الشهدا ... ويسقط الإعذار فيهم أبدا","ومالك فيما رواه أشهب ... قسامة بغير عدل يوجب","أو بمقالة الجريح المسلم ... البالغ الحر فلان بدمي","يشهد عدلان على اعترافه ... وصفة التمييز من أوصافه","أو بقتيل معه قد وجدا ... من أثر القتل عليه قد بدا","وهي بخمسين يمينا وزعت ... على الذكور ولأنثى منعت","بعد ثبوت الموت والولاة ... ويحلفونها على البتات","وتقلب الأيمان مهما نكلا ... ولي مقتول على من قتلا","ويحلف اثنان بها فما علا ... وغير واحد بها لن يقتلا","وليس في عبد ولا جنين ... قسامة ولا عدو الدين","والقود الشرط به المثليه ... في الدم بالإسلام والحريه","وقتل منحط مضى بالعالي ... لا العكس والنساء كالرجال","والشرط في المقتول عصمة الدم ... زيادة لشرطه المستقدم","وإن ولي الدم للمال قبل ... والقود استحقه فيمن قتل","فأشهب قال للاستحياء ... يجبر قاتل على الإعطاء","وليس ذا في مذهب ابن القاسم ... دون اختيار قاتل بلازم","وعفو بعض مسقط القصاص ... ما لم يكن من قعدد انتقاص","وشبهة تدرؤه وملك ... بعض دم الذي اعتراه الهلك","وحيث تقوى تهمة في المدعى ... عليه فالسجن له قد شرعا","والعفو لا يغني من القرابه ... في القتل بالغيلة والحرابه","ومائة يجلد بالأحكام ... من عنه يعفى مع حبس عام","والصلح في ذاك مع العفو استوى ... كما هما في حكم الإسقاط سوى","ودية العمد كذات الخطأ ... أو ما تراضى فيه بين الملإ","وهي إذا ما قبلت وسلمت ... بحسب الميراث قد تقسمت","وجعلت دية مسلم قتل ... على البوادي مائة من الإبل","والحكم بالتربيع في العمد وجب ... وألف دينار على أهل الذهب","وقدرها على أولي الورق اثنا ... عشر ألف درهم لا أدنى","ونصف ما ذكر في اليهود ... وفي النصارى ثابت الوجود","وفي النساء الحكم تنصيف الديه ... وحاله في كل صنف مغنيه","وتجب الدية في قتل الخطا ... والإبل التخميس فيها قسطا","تحملها عاقلة للقاتل ... وهي القرابة من القبائل","حيث ثبوت قتله بالبينه ... أو بقسامة له معينه","يدفعها الأدنى فالأدنى بحسب ... أحوالهم وحكم تنجيم وجب","من موسر مكلف حر ذكر ... موافق في نحلة وفي مقر","وكونها من مال جان إن تكن ... أقل من ثلث بذا الحكم حسن","كذا على المشهور من معترف ... تؤخذ من عامد مكلف","وفي الجنين غرة من ماله ... أو قيمة كالإرث في استعماله","وغلظت فثلثت في الإبل ... وقومت بالعين في القول الجلي","وهي بالآباء والأمهات ... تختص والأجداد والجدات","ويحلف الذكور كالإناث ... بنسبة الحظوظ في الميراث","وإن يمين عند ذا تنكسر ... يحلفها من حظه موفر","وواحد يجوز أن يحلفا ... حيث انفراده بما تخلفا","وهذه الأحكام طرا تعتمد ... بحيثما يسقط بالشرع القود","وسوغت قسامة الولاة ... في غيبة الجاني على الصفات","وينفذ القصاص إن به ظفر ... إقرارا أو وفاق ما منها ذكر"],[]],["فصل في الجراحات",["جل الجراح عمدها فيها القود ... ودية مع خطر فيها فقد","وفي جراح الخطإ الحكومه ... وخمسة ديتها معلومه","فنصف عشر دية في الموضحه ... وهي التي تلفى لعظم موضحه","في رأس أو وجه كذا المنقله ... عشر بها ونصف عشر معدله","في الموضعين مطلقا وهي التي ... كسر فراش العظم قد تولت","وعشر ونصفه في الهاشمه ... وهي لعظم الرأس تلفى هاشمه","وقيل نصف العشر أو حكومه ... وثلث الدية في المأمومه","وما انتهت للجوف وهي الجائفه ... كذاك والأولى الدماغ كاشفه","ولاجتهاد حاكم موكول ... في غيرها التأديب والتنكيل","وجعلوا الحكومة التقويما ... في كونه معيبا أو سليما","وما تزيد حالة السلامه ... يأخذه أرشا ولا ملامه","ويثبت الجراح للمال بما ... يثبت مالي الحقوق فاعلما","وفي ادعاء العفو من ولي دم ... أو من جريح اليمين تلتزم","وقود في القطع للأعضاء ... في العمد ما لم يفض للفناء","والخطأ الدية فيه تقتفى ... بحسب العضو الذي قد أتلفا","ودية كاملة في المزدوج ... ونصفها في واحد منه انتهج","وفي اللسان كملت والذكر ... والأنف والعقل وعين الأعور","وفي إزالة لسمع أو بصر ... والنصف في النصف وشم كالنظر","والنطق والصوت كذا الذوق وفي ... إذهاب قوة الجماع ذا اقتفي","وكل سن فيه من جنس الإبل ... خمس وفي الاصبع ضعفها جعل","ودية الجروح في النساء ... كدية الرجال بالسواء","إلا إذا زادت على ثلت الديه ... فما لها من بعد ذاك تسويه"],[]],["باب التوارث والفرائض",["الإرث يستوجب شرعا ووجب ... بعصمة أو بولاء أو نسب","جميعها أركانه ثلاثه ... مال ومقدار وذو الوراثه"],[]],["فصل في ذكر الوارثين",["ذكور من حق له الميراث ... عشرة وسبع الإناث","الأب والجد له وإن علا ... ما لم يكن عنه بأنثى فصلا","والزوج وابن وابنه هب سفلا ... كذاك مولى نعمة أو بولا","والأخ وابن الأخ لا للأم ... والعم لا للأم وابن العم","والأم والزوجة ثم البنت ... وابنة الإبن بعدها والأخت","وجدة للجهتين ما علت ... ما لم تكن بذكر قد فصلت","كذاك مولاة لها العتق ولا ... حق لها فيما يكون بالولا","وبيت مال المسلمين يستقل ... بحيث لا وارث أو بما فضل"],[]],["فصل في ذكر أحوال الميراث",["الحال في الميراث قد تقسما ... إلى وجوب ولحجب قسما","لحجب الإسقاط أو النقل وذا ... لفرض أو تعصيب أبدى منفذا"],[]],["فصل في ذكر المقدار الذي يكون به الإرث",["القدر يلفى باشتراك فيه ... في جملة المتروك أو باقيه","أو بانفراد باحتياز المال ... أجمع فيه وهو في الرجال","عدا أخا للأم والزوج وفي ... مولاة نعمى حكم ذلك اقتفي"],[]],["فصل في ذكر حالات وجوب الميراث",["ويحصل الميراث حيث حتما ... بف وةرض أو تعصيب أو كليهما","والمال يحوي عاصب منفرد ... أو ما عن الفروض بعد يوجد","وقسمة في الحالتين معمله ... إما على تفاضل أو معدله"],[]],["فصل في ذكر أهل الفرائض وأصولها",["ثم الفرائض البسائط الأول ... ستة الأصول منها في العمل","أولها النصف لخمسة جعل ... البنت والزوج إذا لم ينتقل","ولابنة ابن ولأخت لا لأم ... ونصفه الربع به الزوجين أم","ونصفه الثمن لزوجة وفي ... تعدد قسمة حظيها اقتفي","والثلثان حصة لأربع ... بنات صلب وبنات ابن فعي","والأخت لا للأم في التعداد ... والثلث للجد برجح باد","والأم دون حاجب والأخوه ... لها وهم في قسم ذاك إسوه","ونصفه السدس لأم والأب ... ولإبنة ابن ولجد اجتبي","وجدة ولأخ من أم ... وأشمل لأخت جهة في الحكم","فإن يضق عن الفروض المال ... فالعول إذ ذاك له استعمال","والربع كالثلث وكالثلثين ... تعدمه فريضة مثلين","وثمن بالربع غير ملتقي ... وغير ذاك مطلقا قد يلتقي","والأصل بالتركيب ضعف سته ... وضعفها لا غير ذين البته"],[]],["فصل في ذكر حجب الإسقاط",["ولا سقوط لأب ولا ولد ... ولا لزوجين ولا أم فقد","والجد يحجبه الأدنى والأب ... كذا ابن الأبناء بالأعلى يحجب","وبأب وابن وبابن ابن حجب ... إخوة من مات فلا شيء يجب","كذا بنو الإخوة أيضا حجبوا ... بالجد والإخوة ضمهم أب","والجد بالحجب لإخوة دها ... فيما انتمت لمالك وشبهها","وابن أخ بالحجب للعم وفا ... والعم لابن العم ما كان كفى","والأم كلتا الجدتين تحجب ... وجدة للأب يحجب الأب","ومن دنت حاجبة لبعدى ... جهتها من غير أن تعدى","وقربى الأم حجبت بعدى لأب ... والعكس إن أتى فما حجب وجب","وحظها السدس في الإنفراد ... وقسمة السواء في التعداد","والإرث لم يحزه من هاتين ... تعددا أكثر من ثنتين","ومسقط ذو جهتين أبدا ... ذا جهة مهما تساووا قعددا","ومن له حجب بحاجب حجب ... فحجبه بمن له الحجب يجب","وإخوة الأم بمن يكون في ... عمودي النسب حجبهم يفي"],[]],["فصل في حجب النقل إلى فرض",["الأب مع فروض الاستغراق ... والنقص يحوي السدس بالإطلاق","كذاك يحوي مع ذكران الولد ... أو ولد ابن مثلهم سدسا فقد","والسدس مع أنثى من الصنفين له ... والباقي بالتعصيب بعد حصله","والجد مثل الأب مع من ذكرا ... حالا بحال في الذي تقررا","وزاد بالثلث إن الرجح ظهر ... مع صنف الإخوة وقسم كذكر","والسدس إن يرجح له متى صحب ... أهل الفروض صنف إخوة يجب","أو قسمة السواء في البقيه ... أو ثلثها إلا في الأكدريه","فالعول للأخت بها قد أعملا ... واجمعهما واقسم وجدا فضلا","والقسم مع شقائق ومن لأب ... معا له وعد كلهم وجب","وحظ من للأب للأشقا ... وحدهم يكون مستحقا","والأخت من أب وإن تعددت ... مع شقيقة بسدس أفردت","تكملة الثلثين والحكم كذا ... مع بنت صلب لابنة ابن يحتذا","والزوج من نصف لربع انتقل ... مع ولد أو ولد ابن هب سفل","وينقل الزوجة من ربع إلى ... ثمن صحيح نسبة من هؤلا","والأم من ثلث لسدس تفرد ... بهم وبالإخوة إن تعددوا","وغير من يرث ليس يحجب ... إلا أولاء حجبوا إذ حجبوا","وثلث ما يبقى عن الزوجين ... تأخذ مع أب بغراوين"],[]],["فصل في ذكر حجب النقل للتعصيب",["للإبن شرعا حظ بنتين ادفع ... من مال أو باقيه في التنوع","وولد ابن مثلهم في الحكم ... وإخوة كذا لغير الأم","والأخت لا للأم كيف تأتي ... من شأنها التعصيب مع بنات","كذا يعصبن بنات الإبن ... والعول في الصنفين عنه استغني","وبنت الإبن إن تكن قد حجبت ... بابن مساو أو أحط عصبت","وبأخ لا بابنه أخوات الأب ... تعصبهن مع شقيقات وجب"],[]],["فصل في ذكر موانع الميراث",["الكفر والرق لإرث منعا ... وإن هما بعد الممات ارتفعا","ومثل ذاك الحكم في المرتد ... ومطلقا يمنع قتل العمد","وإن يكن عن خطإ فمن ديه ... وحالة الشك بمنع مغنيه","ويوقف القسم مع الحمل إلى ... أن يستهل صارخا فيعملا","وبين من مات بهدم أو غرق ... يمتنع الإرث لجهل من سبق","وإرث خنثى بمباله اعتبر ... وما بدا عليه في الحكم اقتصر","وإن يبل بالجهتين الخنثى ... فنصف حظي ذكر وأنثى","وابن اللعان إرثه بأمه ... ما كان والسدس أقصى سهمه","وتوأماه هبهما تعددا ... هما شقيقان في الإرث أبدا","وما قصدت جمعه هنا انتهى ... والحمد لله بغير منتهى","وبالصلاة ختمه كما ابتدي ... على الرسول المصطفى محمد","وآله وصحبه الأخيار ... ما كور الليل على النهار","(تمت)"],[]]]);
